  lesson_id, stable_key, position, section, format, payload,
  is_original, points, active
)
select
  lesson.id,
  source.stable_key,
  source.position,
  source.section,
  source.format,
  source.payload,
  source.is_original,
  source.points,
  true
from (
  values
    ('july-04', 'july-04-original-q1', 0, 'Original Review', 'situation', '{"id":"july-04-original-q1","type":"situation","cat":"core","situationQuote":{"en":"You want to tell the real reason softly before giving new information."},"prompt":{"en":"Which word naturally means 「実は」 at the beginning of a sentence?","jp":"文の最初で「実は」と自然に言いたい時、どれを使いますか？"},"choices":[{"id":"a","en":"Actually","jp":"実は / 実際は"},{"id":"b","en":"Always","jp":"いつも / 常に"},{"id":"c","en":"Avoid","jp":"避ける"},{"id":"d","en":"Gratitude","jp":"感謝"}],"correct":"a","hint":{"en":"It often starts a sentence when you share the real information.","jp":"本当の情報を言う時、文の最初によく使います。"},"explanation":{"en":"“Actually” is natural for adding true or slightly surprising information: “Actually, I’m a little tired today.”","jp":"“Actually” は「実は」と本当のことを言う時に自然です。例：Actually, I’m a little tired today."},"legacyId":"q1","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q2', 1, 'Original Review', 'mcq', '{"id":"july-04-original-q2","type":"mcq","cat":"core","prompt":{"en":"Which sentence is grammatically natural?","jp":"文法的に自然なのはどれですか？"},"choices":[{"id":"a","en":"I avoid driving when I’m tired.","jp":"疲れている時は運転を避けます。"},{"id":"b","en":"I avoid to drive when I’m tired.","jp":"avoid to do は不自然です。"},{"id":"c","en":"I avoid drive when I’m tired.","jp":"動詞の形が不自然です。"},{"id":"d","en":"I avoiding driving when I’m tired.","jp":"be 動詞がないので不自然です。"}],"correct":"a","hint":{"en":"After avoid, use a noun or -ing.","jp":"avoid の後は名詞か ing 形です。"},"explanation":{"en":"Use “avoid + -ing”: I avoid driving, avoid eating, avoid using difficult words.","jp":"avoid の後は “driving / eating / using” のように ing 形が自然です。"},"legacyId":"q2","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q3', 2, 'Original Review', 'mcq', '{"id":"july-04-original-q3","type":"mcq","cat":"core","prompt":{"en":"True or False: “avoid to do” is the normal pattern in English.","jp":"True or False：“avoid to do” は普通の英語の形です。"},"choices":[{"id":"a","en":"True","jp":"正しい"},{"id":"b","en":"False","jp":"違う"}],"correct":"b","hint":{"en":"Think: avoid doing.","jp":"avoid doing を思い出しましょう。"},"explanation":{"en":"False. The natural pattern is “avoid doing,” not “avoid to do.”","jp":"False です。自然なのは “avoid doing” で、“avoid to do” ではありません。"},"legacyId":"q3","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q4', 3, 'Original Review', 'situation', '{"id":"july-04-original-q4","type":"situation","cat":"unavoidable","situationQuote":{"en":"The train was cancelled, and there is nothing you can change now."},"prompt":{"en":"Which phrase fits best?","jp":"この場面に一番合う表現はどれですか？"},"choices":[{"id":"a","en":"It can’t be helped.","jp":"仕方ない / やむを得ない。"},{"id":"b","en":"I’m the sleepiest.","jp":"私が一番眠い。"},{"id":"c","en":"Did you do that on purpose?","jp":"それわざとやったの？"},{"id":"d","en":"Actually, I like coffee.","jp":"実はコーヒーが好きです。"}],"correct":"a","hint":{"en":"Use this when you accept a situation you cannot change.","jp":"変えられない状況を受け入れる時の表現です。"},"explanation":{"en":"“It can’t be helped” means 仕方ない or やむを得ない.","jp":"“It can’t be helped.” は「仕方ない / やむを得ない」という意味です。"},"legacyId":"q4","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q5', 4, 'Original Review', 'mcq', '{"id":"july-04-original-q5","type":"mcq","cat":"unavoidable","prompt":{"en":"Which phrase means 「選択肢がない / そうするしかない」?","jp":"「選択肢がない / そうするしかない」はどれですか？"},"choices":[{"id":"a","en":"I have no choice.","jp":"選択肢がない。"},{"id":"b","en":"I have no purpose.","jp":"目的がない、という意味になります。"},{"id":"c","en":"I have no sleepy.","jp":"不自然です。"},{"id":"d","en":"I have no mention.","jp":"不自然です。"}],"correct":"a","hint":{"en":"Choice = 選択肢.","jp":"choice は「選択肢」です。"},"explanation":{"en":"“I have no choice” is natural when you must do something even if you do not really want to.","jp":"“I have no choice.” は、したくなくても他に選択肢がない時に自然です。"},"legacyId":"q5","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q6', 5, 'Original Review', 'situation', '{"id":"july-04-original-q6","type":"situation","cat":"unavoidable","situationQuote":{"en":"You missed an event because an unexpected problem happened."},"prompt":{"en":"What is the most natural casual explanation?","jp":"急な事情で行けなかった時、カジュアルで自然な説明はどれですか？"},"choices":[{"id":"a","en":"Something came up, so I couldn’t make it.","jp":"急な事情があって行けませんでした。"},{"id":"b","en":"Something went down, so I couldn’t make it.","jp":"この意味では不自然です。"},{"id":"c","en":"Something became, so I couldn’t go.","jp":"文として不自然です。"},{"id":"d","en":"I was always, so I couldn’t make it.","jp":"意味が通りません。"}],"correct":"a","hint":{"en":"“Came up” means something unexpected happened.","jp":"came up は「急なことが起きた」という意味で使えます。"},"explanation":{"en":"“Something came up” is a very natural way to avoid giving too many personal details.","jp":"“Something came up.” は、詳しく言いすぎず「急な事情があった」と言える自然な表現です。"},"legacyId":"q6","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q7', 6, 'Original Review', 'mcq', '{"id":"july-04-original-q7","type":"mcq","cat":"unavoidable","prompt":{"en":"Which version sounds more formal and polite?","jp":"よりフォーマルで丁寧に聞こえるのはどれですか？"},"choices":[{"id":"a","en":"Due to unavoidable circumstances, I couldn’t attend.","jp":"やむを得ない事情により、参加できませんでした。"},{"id":"b","en":"I don’t want to get old.","jp":"歳とりたくない。"},{"id":"c","en":"Don’t mention it.","jp":"いえいえ。"},{"id":"d","en":"I’m just sitting here.","jp":"ただ座ってるだけ。"}],"correct":"a","hint":{"en":"Formal emails often use “Due to... circumstances.”","jp":"丁寧なメールでは “Due to... circumstances” がよく合います。"},"explanation":{"en":"This phrase is more formal than “Something came up.”","jp":"これは “Something came up.” よりフォーマルで丁寧な表現です。"},"legacyId":"q7","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q8', 7, 'Original Review', 'mcq', '{"id":"july-04-original-q8","type":"mcq","cat":"danger","prompt":{"en":"Mistake Detective: Which phrase is unnatural for 「事故を起こす / 事故に遭う」?","jp":"ミス発見：「事故を起こす / 事故に遭う」で不自然なのはどれですか？"},"choices":[{"id":"a","en":"make an accident","jp":"不自然です。"},{"id":"b","en":"have an accident","jp":"自然です。"},{"id":"c","en":"get into an accident","jp":"自然です。"},{"id":"d","en":"crash","jp":"自然です。"}],"correct":"a","hint":{"en":"In English, you do not usually “make” an accident.","jp":"英語では普通 “make an accident” とは言いません。"},"explanation":{"en":"Say “have an accident,” “get into an accident,” or “crash.”","jp":"“have an accident,” “get into an accident,” “crash” が自然です。"},"legacyId":"q8","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q9', 8, 'Original Review', 'situation', '{"id":"july-04-original-q9","type":"situation","cat":"danger","situationQuote":{"en":"You are driving on a scary highway. The cars are very fast."},"prompt":{"en":"Choose the natural sentence.","jp":"自然な文を選んでください。"},"choices":[{"id":"a","en":"If I crashed on this highway, I’d be dead for sure.","jp":"この高速で事故ったら、確実に死んでるわ。"},{"id":"b","en":"If I made an accident, I’m sleepy for sure.","jp":"意味も文法も不自然です。"},{"id":"c","en":"If I avoid on this highway, I’d gratitude.","jp":"文として不自然です。"},{"id":"d","en":"If I purpose on this highway, I’d old.","jp":"文として不自然です。"}],"correct":"a","hint":{"en":"Crash = 事故る / 衝突する.","jp":"crash は「事故る / 衝突する」です。"},"explanation":{"en":"This is a casual but powerful way to describe a dangerous road.","jp":"危険な道路について言う時、カジュアルでリアルな表現です。"},"legacyId":"q9","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q10', 9, 'Original Review', 'mcq', '{"id":"july-04-original-q10","type":"mcq","cat":"feelings","prompt":{"en":"Which sentence means 「歳とりたくない」?","jp":"「歳とりたくない」はどれですか？"},"choices":[{"id":"a","en":"I don’t want to get old.","jp":"歳とりたくない。"},{"id":"b","en":"I don’t want to be always.","jp":"不自然です。"},{"id":"c","en":"I don’t want to appreciate.","jp":"感謝したくない、という変な意味です。"},{"id":"d","en":"I don’t want to mention.","jp":"この場面では不自然です。"}],"correct":"a","hint":{"en":"get old = 年を取る.","jp":"get old は「年を取る」です。"},"explanation":{"en":"“I don’t want to get old” is simple and very natural.","jp":"“I don’t want to get old.” はシンプルで自然です。"},"legacyId":"q10","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q11', 10, 'Original Review', 'situation', '{"id":"july-04-original-q11","type":"situation","cat":"feelings","situationQuote":{"en":"Someone thinks you are doing something special, but you are doing nothing special."},"prompt":{"en":"Which sentence fits 「ただ座ってるだけだけどね」?","jp":"「ただ座ってるだけだけどね」に合う文はどれですか？"},"choices":[{"id":"a","en":"I’m just sitting here, though.","jp":"ただ座ってるだけだけどね。"},{"id":"b","en":"I’m just avoiding here, though.","jp":"ここでは不自然です。"},{"id":"c","en":"I’m just gratitude here, though.","jp":"文として不自然です。"},{"id":"d","en":"I’m just purpose here, though.","jp":"文として不自然です。"}],"correct":"a","hint":{"en":"Use the present continuous: I’m sitting.","jp":"今していることなので I’m sitting を使います。"},"explanation":{"en":"Adding “though” at the end gives a natural 「だけどね」 feeling.","jp":"最後に though をつけると「だけどね」という自然な感じになります。"},"legacyId":"q11","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q12', 11, 'Original Review', 'mcq', '{"id":"july-04-original-q12","type":"mcq","cat":"intention","prompt":{"en":"Which phrase means 「わざと」 in everyday conversation?","jp":"日常会話で「わざと」はどれですか？"},"choices":[{"id":"a","en":"on purpose","jp":"わざと"},{"id":"b","en":"on sleepy","jp":"不自然です。"},{"id":"c","en":"on gratitude","jp":"不自然です。"},{"id":"d","en":"on always","jp":"不自然です。"}],"correct":"a","hint":{"en":"Purpose = 目的. On purpose = intentionally.","jp":"purpose は目的。on purpose は「わざと」です。"},"explanation":{"en":"“on purpose” is the most useful everyday phrase for わざと.","jp":"“on purpose” は「わざと」の日常会話で一番使いやすい表現です。"},"legacyId":"q12","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q13', 12, 'Original Review', 'mcq', '{"id":"july-04-original-q13","type":"mcq","cat":"intention","prompt":{"en":"Fix-It Challenge: Choose the natural question for 「それわざとやったの？」","jp":"修正チャレンジ：「それわざとやったの？」の自然な英語はどれですか？"},"choices":[{"id":"a","en":"Did you do that on purpose?","jp":"それわざとやったの？"},{"id":"b","en":"Did you do that on gratitude?","jp":"不自然です。"},{"id":"c","en":"Were you do that on purpose?","jp":"文法が不自然です。"},{"id":"d","en":"Did you that purpose?","jp":"文法が不自然です。"}],"correct":"a","hint":{"en":"Past question: Did you + base verb.","jp":"過去の質問は Did you + 動詞の原形です。"},"explanation":{"en":"“Did you do that on purpose?” is the natural daily phrase.","jp":"“Did you do that on purpose?” が自然な日常表現です。"},"legacyId":"q13","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q14', 13, 'Original Review', 'mcq', '{"id":"july-04-original-q14","type":"mcq","cat":"gratitude","prompt":{"en":"Which word is a noun meaning 「感謝 / 感謝の気持ち」?","jp":"名詞で「感謝 / 感謝の気持ち」はどれですか？"},"choices":[{"id":"a","en":"gratitude","jp":"感謝 / 感謝の気持ち"},{"id":"b","en":"grateful","jp":"形容詞：感謝している"},{"id":"c","en":"appreciate","jp":"動詞：感謝する"},{"id":"d","en":"purpose","jp":"目的"}],"correct":"a","hint":{"en":"A noun names a person, place, thing, or idea.","jp":"名詞は、人・場所・もの・考えなどの名前を表します。"},"explanation":{"en":"“gratitude” is the noun. “grateful” is an adjective, and “appreciate” is a verb.","jp":"“gratitude” は名詞、“grateful” は形容詞、“appreciate” は動詞です。"},"legacyId":"q14","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q15', 14, 'Original Review', 'situation', '{"id":"july-04-original-q15","type":"situation","cat":"gratitude","situationQuote":{"en":"Someone helped you a lot, and you want to sound natural and sincere."},"prompt":{"en":"Which phrase is the best daily expression?","jp":"日常で一番使いやすく自然な感謝表現はどれですか？"},"choices":[{"id":"a","en":"I really appreciate it.","jp":"本当にありがとう / 本当に感謝しています。"},{"id":"b","en":"I really gratitude it.","jp":"gratitude は名詞なので不自然です。"},{"id":"c","en":"I really grateful it.","jp":"grateful は形容詞なので不自然です。"},{"id":"d","en":"I really purpose it.","jp":"不自然です。"}],"correct":"a","hint":{"en":"appreciate is a verb.","jp":"appreciate は動詞です。"},"explanation":{"en":"“I really appreciate it” is one of the most useful daily gratitude phrases.","jp":"“I really appreciate it.” は日常でとても使いやすい感謝表現です。"},"legacyId":"q15","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q16', 15, 'Original Review', 'situation', '{"id":"july-04-original-q16","type":"situation","cat":"gratitude","situationQuote":{"en":"A: Thank you for helping me."},"prompt":{"en":"Which reply means 「いえいえ / 気にしないで」?","jp":"「いえいえ / 気にしないで」という返事はどれですか？"},"choices":[{"id":"a","en":"Don’t mention it.","jp":"いえいえ / 気にしないで。"},{"id":"b","en":"Don’t purpose it.","jp":"不自然です。"},{"id":"c","en":"Don’t avoid it.","jp":"避けないで、という意味です。"},{"id":"d","en":"Don’t sleepy it.","jp":"不自然です。"}],"correct":"a","hint":{"en":"It is a polite reply to “Thank you.”","jp":"Thank you への丁寧で自然な返事です。"},"explanation":{"en":"“Don’t mention it” means the person does not need to thank you too much.","jp":"“Don’t mention it.” は「お礼なんていいよ / 気にしないで」という感じです。"},"legacyId":"q16","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q17', 16, 'Original Review', 'mcq', '{"id":"july-04-original-q17","type":"mcq","cat":"grammar","prompt":{"en":"Which is the most natural superlative of “sleepy”?","jp":"sleepy の一番自然な最上級はどれですか？"},"choices":[{"id":"a","en":"sleepiest","jp":"一番眠い"},{"id":"b","en":"most sleepy","jp":"意味はわかるけど、普通は sleepiest が自然。"},{"id":"c","en":"sleepyest","jp":"スペルが違います。"},{"id":"d","en":"sleepily","jp":"副詞です。"}],"correct":"a","hint":{"en":"sleepy → sleepier → sleepiest.","jp":"sleepy → sleepier → sleepiest です。"},"explanation":{"en":"The natural form is sleepiest: “This is the sleepiest I’ve ever been.”","jp":"自然なのは sleepiest です。例：This is the sleepiest I’ve ever been."},"legacyId":"q17","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q18', 17, 'Original Review', 'mcq', '{"id":"july-04-original-q18","type":"mcq","cat":"grammar","prompt":{"en":"Which sentence sounds most natural in daily conversation?","jp":"日常会話で一番自然なのはどれですか？"},"choices":[{"id":"a","en":"I might be late.","jp":"遅れるかもしれない。"},{"id":"b","en":"I may late.","jp":"be が必要です。"},{"id":"c","en":"I might to be late.","jp":"to は不要です。"},{"id":"d","en":"I might being late.","jp":"形が不自然です。"}],"correct":"a","hint":{"en":"might + base verb / be.","jp":"might の後は動詞の原形です。"},"explanation":{"en":"“I might be late” is natural and common. “May” can also mean 〜かもしれない, but it sounds a little more formal.","jp":"“I might be late.” は自然でよく使います。may も使えますが、少し丁寧・硬めです。"},"legacyId":"q18","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q19', 18, 'Original Review', 'mcq', '{"id":"july-04-original-q19","type":"mcq","cat":"grammar","prompt":{"en":"Which sentence puts “always” in the right place?","jp":"always の位置が正しい文はどれですか？"},"choices":[{"id":"a","en":"I am always tired.","jp":"私はいつも疲れています。"},{"id":"b","en":"I always am tired.","jp":"会話では少し不自然です。"},{"id":"c","en":"I tired always am.","jp":"語順が不自然です。"},{"id":"d","en":"Always I am tired.","jp":"文脈によって可能ですが、普通の語順ではありません。"}],"correct":"a","hint":{"en":"With a form of be, always usually comes after the verb.","jp":"be動詞の後に always を置くのが基本です。"},"explanation":{"en":"With the verb be: I am always tired. With action verbs: I always eat breakfast.","jp":"be動詞なら I am always tired. 一般動詞なら I always eat breakfast. です。"},"legacyId":"q19","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q20', 19, 'Original Review', 'order', '{"id":"july-04-original-q20","type":"order","cat":"builder","prompt":{"en":"Sentence Builder: Make 「実は、今日は少し疲れています。」","jp":"文を組み立てましょう：「実は、今日は少し疲れています。」"},"words":["tired","Actually,","a little","today","I’m"],"correctOrder":[1,4,2,0,3],"hint":{"en":"Start with Actually, then I’m...","jp":"Actually, で始めて、I’m... と続けます。"},"explanation":{"en":"The natural sentence is “Actually, I’m a little tired today.”","jp":"自然な文は “Actually, I’m a little tired today.” です。"},"legacyId":"q20","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q21', 20, 'Original Review', 'order', '{"id":"july-04-original-q21","type":"order","cat":"builder","prompt":{"en":"Sentence Builder: Make 「疲れている時は運転を避けます。」","jp":"文を組み立てましょう：「疲れている時は運転を避けます。」"},"words":["when","driving","tired","I","avoid","I’m"],"correctOrder":[3,4,1,0,5,2],"hint":{"en":"Use avoid + driving.","jp":"avoid + driving を使います。"},"explanation":{"en":"The natural sentence is “I avoid driving when I’m tired.”","jp":"自然な文は “I avoid driving when I’m tired.” です。"},"legacyId":"q21","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q22', 21, 'Original Review', 'order', '{"id":"july-04-original-q22","type":"order","cat":"builder","prompt":{"en":"Sentence Builder: Make 「急な事情があって行けませんでした。」","jp":"文を組み立てましょう：「急な事情があって行けませんでした。」"},"words":["make","up,","it","couldn’t","Something","came","so I"],"correctOrder":[4,5,1,6,3,0,2],"hint":{"en":"Start with “Something came up...”","jp":"“Something came up...” から始めます。"},"explanation":{"en":"The natural sentence is “Something came up, so I couldn’t make it.”","jp":"自然な文は “Something came up, so I couldn’t make it.” です。"},"legacyId":"q22","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q23', 22, 'Original Review', 'matching', '{"id":"july-04-original-q23","type":"matching","cat":"mixed","prompt":{"en":"Speed Match: Match today’s phrases with the Japanese meaning.","jp":"スピードマッチ：今日の表現と日本語の意味を合わせましょう。"},"hint":{"en":"Match the meaning, not only the word order.","jp":"語順ではなく、意味で合わせましょう。"},"pairs":[{"en":"Actually","jp":"実は","cat":"core"},{"en":"avoid","jp":"避ける","cat":"core"},{"en":"It can’t be helped.","jp":"仕方ない。","cat":"unavoidable"},{"en":"Something came up.","jp":"急な事情が起きた。","cat":"unavoidable"},{"en":"crash","jp":"事故る / 衝突する","cat":"danger"},{"en":"I don’t want to get old.","jp":"歳とりたくない。","cat":"feelings"},{"en":"on purpose","jp":"わざと","cat":"intention"},{"en":"I really appreciate it.","jp":"本当に感謝しています。","cat":"gratitude"},{"en":"sleepiest","jp":"一番眠い","cat":"grammar"},{"en":"Don’t mention it.","jp":"いえいえ / 気にしないで","cat":"gratitude"}],"legacyId":"q23","section":"Original Review","isOriginal":true}'::jsonb, true, 10),
    ('july-04', 'july-04-original-q24', 23, 'Original Review', 'typing', '{"id":"july-04-original-q24","type":"typing","cat":"unavoidable","promptJP":"「仕方ない。」","accepted":["It can''t be helped","It cannot be helped"],"hint":{"en":"Use can’t be helped.","jp":"can’t be helped を使います。"},"explanation":{"en":"“It can’t be helped” is a natural phrase for 仕方ない.","jp":"“It can’t be helped.” は「仕方ない」に自然です。"},"legacyId":"q24","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q25', 24, 'Original Review', 'typing', '{"id":"july-04-original-q25","type":"typing","cat":"danger","promptJP":"「もしこの高速で事故ったら、確実に死んでるわ。」","accepted":["If I crashed on this highway I''d be dead for sure","If I crashed on this highway, I''d be dead for sure","If I crashed on this highway I would be dead for sure","If I crashed on this highway, I would be dead for sure"],"hint":{"en":"Use crashed and dead for sure.","jp":"crashed と dead for sure を使います。"},"explanation":{"en":"This is a vivid, natural way to talk about a dangerous highway.","jp":"危ない高速について言う時、リアルで自然な表現です。"},"legacyId":"q25","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q26', 25, 'Original Review', 'typing', '{"id":"july-04-original-q26","type":"typing","cat":"intention","promptJP":"「それわざとやったの？」","accepted":["Did you do that on purpose"],"hint":{"en":"Did you + do + that + on purpose.","jp":"Did you + do + that + on purpose です。"},"explanation":{"en":"“Did you do that on purpose?” is the natural question.","jp":"“Did you do that on purpose?” が自然な質問です。"},"legacyId":"q26","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-original-q27', 26, 'Original Review', 'typing', '{"id":"july-04-original-q27","type":"typing","cat":"gratitude","promptJP":"「本当に感謝しています。」","accepted":["I really appreciate it","I''m really grateful","I am really grateful"],"hint":{"en":"The daily phrase is I really appreciate it.","jp":"日常で一番使いやすいのは I really appreciate it. です。"},"explanation":{"en":"“I really appreciate it” is direct, natural, and useful.","jp":"“I really appreciate it.” は自然でとても使いやすい感謝表現です。"},"legacyId":"q27","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-04', 'july-04-extra-listen-choice-1', 27, 'Listen & Speak', 'listenChoice', '{"id":"july-04-extra-listen-choice-1","format":"listenChoice","type":"listenChoice","section":"Listen & Speak","topic":"conversation","isOriginal":false,"hint":"Actually で本当の情報を加える。","hintJa":"Actually で本当の情報を加える。","explanation":"Actually で本当の情報を加える。","explanationJa":"Actually で本当の情報を加える。","prompt":"Listen and choose the sentence you hear.","promptJa":"音声を聞いて、聞こえた英文を選んでください。","audioText":"Actually, I’m a little tired today.","choices":[{"id":"a","en":"Actually, I’m a little tired today.","jp":"実は今日は少し疲れています。"},{"id":"b","en":"I avoid driving when I’m tired.","jp":"疲れている時は運転を避けます。"},{"id":"c","en":"Something came up.","jp":"急な事情ができました。"},{"id":"d","en":"It can’t be helped.","jp":"仕方ありません。"}],"correct":"a"}'::jsonb, false, 1),
    ('july-04', 'july-04-extra-listen-choice-2', 28, 'Listen & Speak', 'listenChoice', '{"id":"july-04-extra-listen-choice-2","format":"listenChoice","type":"listenChoice","section":"Listen & Speak","topic":"safety","isOriginal":false,"hint":"avoid + 動詞-ing。","hintJa":"avoid + 動詞-ing。","explanation":"avoid + 動詞-ing。","explanationJa":"avoid + 動詞-ing。","prompt":"Listen and choose the sentence you hear.","promptJa":"音声を聞いて、聞こえた英文を選んでください。","audioText":"I avoid driving when I’m tired.","choices":[{"id":"a","en":"I avoid driving when I’m tired.","jp":"疲れている時は運転を避けます。"},{"id":"b","en":"Something came up.","jp":"急な事情ができました。"},{"id":"c","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"d","en":"He didn’t do it on purpose.","jp":"彼はわざとしたのではありません。"}],"correct":"a"}'::jsonb, false, 1),
    ('july-04', 'july-04-extra-dictation-1', 29, 'Listen & Speak', 'listenType', '{"id":"july-04-extra-dictation-1","format":"listenType","type":"listenType","section":"Listen & Speak","topic":"unexpected events","isOriginal":false,"hint":"予定変更の自然な説明。","hintJa":"予定変更の自然な説明。","explanation":"予定変更の自然な説明。","explanationJa":"予定変更の自然な説明。","prompt":"Type the complete sentence you hear.","promptJa":"聞こえた英文をそのまま入力してください。","audioText":"Something came up.","accepted":["Something came up."]}'::jsonb, false, 1),
