    ('july-05', 'july-05-extra-speaking-1', 28, 'Listen & Speak', 'speaking', '{"id":"july-05-extra-speaking-1","format":"speaking","type":"speaking","section":"Listen & Speak","topic":"decisions","isOriginal":false,"hint":"即答を避ける丁寧な表現。","hintJa":"即答を避ける丁寧な表現。","explanation":"即答を避ける丁寧な表現。","explanationJa":"即答を避ける丁寧な表現。","prompt":"Listen, then say the sentence naturally.","promptJa":"音声を聞いてから、自然に言ってみましょう。","speakText":"Let me think about it.","speakJa":"少し考えさせてください。"}'::jsonb, false, 1),
    ('july-05', 'july-05-extra-speaking-2', 29, 'Listen & Speak', 'speaking', '{"id":"july-05-extra-speaking-2","format":"speaking","type":"speaking","section":"Listen & Speak","topic":"opinions","isOriginal":false,"hint":"相手の意見を認める。","hintJa":"相手の意見を認める。","explanation":"相手の意見を認める。","explanationJa":"相手の意見を認める。","prompt":"Listen, then say the sentence naturally.","promptJa":"音声を聞いてから、自然に言ってみましょう。","speakText":"That’s a good point.","speakJa":"それはいい指摘ですね。"}'::jsonb, false, 1),
    ('july-05', 'july-05-extra-true-false', 30, 'Use It', 'truefalse', '{"id":"july-05-extra-true-false","format":"truefalse","type":"truefalse","section":"Use It","topic":"choices","isOriginal":false,"hint":"決定を変えた時。","hintJa":"決定を変えた時。","explanation":"決定を変えた時。","explanationJa":"決定を変えた時。","prompt":"“I changed my mind.” means “考えが変わりました。”.","promptJa":"「I changed my mind.」は「考えが変わりました。」という意味です。","correct":true}'::jsonb, false, 1),
    ('july-05', 'july-05-extra-order', 31, 'Use It', 'order', '{"id":"july-05-extra-order","format":"order","type":"order","section":"Use It","topic":"choices","isOriginal":false,"hint":"either = どちらでも。","hintJa":"either = どちらでも。","explanation":"either = どちらでも。","explanationJa":"either = どちらでも。","prompt":"Put the words in order: どちらの選択肢でも大丈夫です。","promptJa":"語順を並べましょう：どちらの選択肢でも大丈夫です。","words":["option","me","works","Either","for"],"correctWords":["Either","option","works","for","me"]}'::jsonb, false, 1),
    ('july-05', 'july-05-extra-matching', 32, 'Use It', 'matching', '{"id":"july-05-extra-matching","format":"matching","type":"matching","section":"Use It","topic":"reactions","isOriginal":false,"hint":"説明に納得した時。","hintJa":"説明に納得した時。","explanation":"説明に納得した時。","explanationJa":"説明に納得した時。","prompt":"Match each English phrase with its natural Japanese meaning.","promptJa":"英文と自然な日本語を組み合わせてください。","pairs":[{"en":"That makes sense.","jp":"なるほど、筋が通っています。","cat":"reactions"},{"en":"I’d rather stay home tonight.","jp":"今夜は家にいたいです。","cat":"preferences"},{"en":"It depends on the weather.","jp":"天気によります。","cat":"decisions"},{"en":"I’m not sure yet.","jp":"まだ分かりません。","cat":"responses"},{"en":"Let me think about it.","jp":"少し考えさせてください。","cat":"decisions"},{"en":"That’s a good point.","jp":"それはいい指摘ですね。","cat":"opinions"}]}'::jsonb, false, 6),
    ('july-05', 'july-05-extra-sorting', 33, 'Use It', 'sorting', '{"id":"july-05-extra-sorting","format":"sorting","type":"sorting","section":"Use It","topic":"preferences","isOriginal":false,"hint":"would rather + 動詞原形。","hintJa":"would rather + 動詞原形。","explanation":"would rather + 動詞原形。","explanationJa":"would rather + 動詞原形。","prompt":"Sort each phrase by its language purpose.","promptJa":"各表現を目的別に分類してください。","categories":["reactions","preferences"],"items":[["That makes sense.","reactions"],["I’d rather stay home tonight.","preferences"]]}'::jsonb, false, 2),
    ('july-05', 'july-05-extra-dialogue', 34, 'Use It', 'dialogue', '{"id":"july-05-extra-dialogue","format":"dialogue","type":"dialogue","section":"Use It","topic":"preferences","isOriginal":false,"hint":"would rather + 動詞原形。","hintJa":"would rather + 動詞原形。","explanation":"would rather + 動詞原形。","explanationJa":"would rather + 動詞原形。","prompt":"Choose the most natural next line in the conversation.","promptJa":"会話の次に続く最も自然な一文を選んでください。","context":"A: Do you want to go out tonight?\nB: ...","contextJa":"A：「今夜、出かけたい？」\nB：…","choices":[{"id":"a","en":"I’d rather stay home tonight.","jp":"今夜は家にいたいです。"},{"id":"b","en":"I finished it yesterday.","jp":"昨日それを終えました。"},{"id":"c","en":"It’s on the table.","jp":"テーブルの上にあります。"},{"id":"d","en":"The train leaves at seven.","jp":"電車は7時に出ます。"}],"correct":"a"}'::jsonb, false, 1),
    ('july-05', 'july-05-extra-translation', 35, 'Use It', 'translation', '{"id":"july-05-extra-translation","format":"translation","type":"translation","section":"Use It","topic":"decisions","isOriginal":false,"hint":"It depends on...","hintJa":"It depends on...","explanation":"It depends on...","explanationJa":"It depends on...","prompt":"Translate into English: 天気によります。","promptJa":"英語にしてください：天気によります。","accepted":["It depends on the weather."]}'::jsonb, false, 1),
    ('july-05', 'july-05-extra-situation', 36, 'Use It', 'situation', '{"id":"july-05-extra-situation","format":"situation","type":"situation","section":"Use It","topic":"responses","isOriginal":false,"hint":"決まっていない時。","hintJa":"決まっていない時。","explanation":"決まっていない時。","explanationJa":"決まっていない時。","prompt":"Which sentence best expresses this meaning: まだ分かりません。","promptJa":"「まだ分かりません。」に最も合う英文はどれですか？","choices":[{"id":"a","en":"I’m not sure yet.","jp":"まだ分かりません。"},{"id":"b","en":"Let me think about it.","jp":"少し考えさせてください。"},{"id":"c","en":"That’s a good point.","jp":"それはいい指摘ですね。"},{"id":"d","en":"I changed my mind.","jp":"考えが変わりました。"}],"correct":"a"}'::jsonb, false, 1),
    ('july-06', 'july-06-original-q1', 0, 'Original Review', 'situation', '{"id":"july-06-original-q1","type":"situation","cat":"alcohol","prompt":{"en":"Choose the most natural way to say 「今日はまだお酒を飲んでいません」.","jp":"「今日はまだお酒を飲んでいません」と言う時、一番自然なのはどれですか？"},"choices":[{"id":"a","en":"I haven’t had any alcohol yet today.","jp":"今日はまだお酒を飲んでいません。"},{"id":"b","en":"I didn’t drink alcohol yet today.","jp":"didn’t + yet が少し不自然です。"},{"id":"c","en":"I haven’t drink alcohol yet today.","jp":"haven’t の後は過去分詞が必要です。"},{"id":"d","en":"I didn’t drank alcohol today.","jp":"didn’t の後は原形 drink です。"}],"correct":"a","hint":{"en":"For まだ〜していない, present perfect + yet is natural.","jp":"「まだ〜していない」は現在完了 + yet が自然です。"},"explanation":{"en":"“I haven’t had any alcohol yet today” means today is still continuing and up to now you have not drunk.","jp":"今日がまだ続いていて、今の時点でまだ飲んでいないという意味です。"},"situationQuote":{"en":"It is still early in the day. Someone asks: “Did you drink today?”"},"legacyId":"q1","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q2', 1, 'Original Review', 'mcq', '{"id":"july-06-original-q2","type":"mcq","cat":"alcohol","prompt":{"en":"Which sentence sounds like a finished-day result?","jp":"一日を振り返って「今日は飲まなかった」と言う感じの文はどれですか？"},"choices":[{"id":"a","en":"I didn’t drink today.","jp":"今日は飲まなかった。"},{"id":"b","en":"I haven’t had any alcohol yet today.","jp":"まだ今日が続いている感じです。"},{"id":"c","en":"I don’t drinking today.","jp":"文法が不自然です。"},{"id":"d","en":"I didn’t drunk today.","jp":"didn’t の後は drink です。"}],"correct":"a","hint":{"en":"Finished past uses didn’t + verb.","jp":"終わった過去は didn’t + 動詞の原形です。"},"explanation":{"en":"“I didn’t drink today” is natural when you summarize the day as a result.","jp":"“I didn’t drink today.” は結果として「今日は飲まなかった」と言う時に自然です。"},"legacyId":"q2","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q3', 2, 'Original Review', 'mcq', '{"id":"july-06-original-q3","type":"mcq","cat":"alcohol","prompt":{"en":"True or False: “I didn’t drink alcohol yet” is the best standard sentence for 「まだ飲んでいない」.","jp":"True or False：“I didn’t drink alcohol yet” は「まだ飲んでいない」の一番標準的な文です。"},"choices":[{"id":"a","en":"True","jp":"正しい"},{"id":"b","en":"False","jp":"違う"}],"correct":"b","hint":{"en":"Use haven’t ... yet.","jp":"haven’t ... yet を使います。"},"explanation":{"en":"The standard natural sentence is “I haven’t had any alcohol yet.”","jp":"標準的には “I haven’t had any alcohol yet.” が自然です。"},"legacyId":"q3","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q4', 3, 'Original Review', 'mcq', '{"id":"july-06-original-q4","type":"mcq","cat":"alcohol","prompt":{"en":"Choose the correct verb change for drink.","jp":"drink の変化で正しいものを選んでください。"},"choices":[{"id":"a","en":"drink - drank - drunk","jp":"原形 - 過去形 - 過去分詞"},{"id":"b","en":"drink - drunk - drank","jp":"順番が違います。"},{"id":"c","en":"drink - drinked - drinked","jp":"不規則動詞です。"},{"id":"d","en":"drink - drinking - drank","jp":"過去分詞ではありません。"}],"correct":"a","hint":{"en":"Past is drank. Past participle is drunk.","jp":"過去形は drank、過去分詞は drunk です。"},"explanation":{"en":"The verb forms are drink, drank, drunk.","jp":"drink の変化は drink - drank - drunk です。"},"legacyId":"q4","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q5', 4, 'Original Review', 'situation', '{"id":"july-06-original-q5","type":"situation","cat":"hate","prompt":{"en":"Which sentence is natural?","jp":"自然な文はどれですか？"},"choices":[{"id":"a","en":"I hate watching soccer.","jp":"サッカーを見るのが嫌いです。"},{"id":"b","en":"I hate watch soccer.","jp":"hate の後にそのまま原形は置けません。"},{"id":"c","en":"I hate watched soccer.","jp":"この形は不自然です。"},{"id":"d","en":"I hate to soccer watching.","jp":"語順が不自然です。"}],"correct":"a","hint":{"en":"hate + verb-ing.","jp":"hate + 動詞ing です。"},"explanation":{"en":"Use hate + watching when you mean 「見るのが嫌い」.","jp":"「見るのが嫌い」は hate + watching が自然です。"},"situationQuote":{"en":"You don’t like watching soccer on TV."},"legacyId":"q5","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q6', 5, 'Original Review', 'mcq', '{"id":"july-06-original-q6","type":"mcq","cat":"hate","prompt":{"en":"Which sentence is a softer way to say you dislike soccer?","jp":"サッカーがあまり好きではないことをやわらかく言う文はどれですか？"},"choices":[{"id":"a","en":"I’m not really into soccer.","jp":"サッカーにはあまり興味がありません。"},{"id":"b","en":"I hate soccer forever.","jp":"かなり強すぎます。"},{"id":"c","en":"I angry soccer.","jp":"文法が不自然です。"},{"id":"d","en":"Soccer is my behalf.","jp":"意味が違います。"}],"correct":"a","hint":{"en":"not really into = あまり興味がない.","jp":"not really into = あまり興味がない。"},"explanation":{"en":"“I’m not really into soccer” is softer than “I hate soccer.”","jp":"“I’m not really into soccer.” は “I hate soccer.” よりやわらかいです。"},"legacyId":"q6","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q7', 6, 'Original Review', 'mcq', '{"id":"july-06-original-q7","type":"mcq","cat":"hate","prompt":{"en":"Mistake Detective: Which sentence is wrong?","jp":"ミス発見：間違っている文はどれですか？"},"choices":[{"id":"a","en":"I hate watch football.","jp":"hate の後は watching などが必要です。"},{"id":"b","en":"I hate watching football.","jp":"自然です。"},{"id":"c","en":"I hate waiting in line.","jp":"自然です。"},{"id":"d","en":"I hate waking up early.","jp":"自然です。"}],"correct":"a","hint":{"en":"Look after hate.","jp":"hate の後ろを見ましょう。"},"explanation":{"en":"“I hate watch football” is wrong because hate needs a gerund like watching or an infinitive like to watch.","jp":"hate の後は watching や to watch が必要です。"},"legacyId":"q7","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q8', 7, 'Original Review', 'situation', '{"id":"july-06-original-q8","type":"situation","cat":"prepositions","prompt":{"en":"Which sentence is natural?","jp":"自然な文はどれですか？"},"choices":[{"id":"a","en":"I found this café on Instagram.","jp":"このカフェをインスタで見つけました。"},{"id":"b","en":"I found this café in Instagram.","jp":"普通は不自然です。"},{"id":"c","en":"I found this café at Instagram.","jp":"会社・場所の at なので違います。"},{"id":"d","en":"I found this café of Instagram.","jp":"前置詞が違います。"}],"correct":"a","hint":{"en":"SNS and websites usually use on.","jp":"SNSやウェブサイトは基本 on を使います。"},"explanation":{"en":"We say on Instagram, on YouTube, on TikTok, on the internet, and on a website.","jp":"Instagram、YouTube、TikTok、internet、website には基本的に on を使います。"},"situationQuote":{"en":"You found a nice café while using Instagram."},"legacyId":"q8","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q9', 8, 'Original Review', 'mcq', '{"id":"july-06-original-q9","type":"mcq","cat":"prepositions","prompt":{"en":"Which sentence means 「コメント欄の中で見ました」?","jp":"「コメント欄の中で見ました」はどれですか？"},"choices":[{"id":"a","en":"I saw it in the comments.","jp":"コメント欄の中で見ました。"},{"id":"b","en":"I saw it on the comments.","jp":"コメント欄の中なら in が自然です。"},{"id":"c","en":"I saw it at the comments.","jp":"at は不自然です。"},{"id":"d","en":"I saw it by comments.","jp":"意味が違います。"}],"correct":"a","hint":{"en":"Inside a section = in.","jp":"中にある感じは in です。"},"explanation":{"en":"Use in when you mean inside a section, like “in the comments.”","jp":"コメント欄の中は “in the comments” が自然です。"},"legacyId":"q9","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q10', 9, 'Original Review', 'mcq', '{"id":"july-06-original-q10","type":"mcq","cat":"prepositions","prompt":{"en":"Which sentence means she works for Instagram as a company?","jp":"彼女がInstagramという会社で働いている、という意味の文はどれですか？"},"choices":[{"id":"a","en":"She works at Instagram.","jp":"彼女はInstagram社で働いています。"},{"id":"b","en":"She works on Instagram.","jp":"インスタ上で活動している感じになることがあります。"},{"id":"c","en":"She works in Instagram.","jp":"普通は不自然です。"},{"id":"d","en":"She works by Instagram.","jp":"不自然です。"}],"correct":"a","hint":{"en":"For a company/workplace, use at.","jp":"会社・職場には at を使います。"},"explanation":{"en":"Use at for a company or workplace: She works at Instagram.","jp":"会社・職場として言う時は at を使います。"},"legacyId":"q10","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q11', 10, 'Original Review', 'matching', '{"id":"july-06-original-q11","type":"matching","cat":"part1","prompt":{"en":"Part 1 Match: Connect the sentence with the meaning.","jp":"Part 1 マッチ：英語と日本語を合わせましょう。"},"hint":{"en":"Focus on situation and grammar shape.","jp":"場面と文法の形に注目しましょう。"},"pairs":[{"en":"I haven’t had any alcohol yet.","jp":"まだお酒を飲んでいません。","cat":"part1"},{"en":"I didn’t drink yesterday.","jp":"昨日は飲みませんでした。","cat":"part1"},{"en":"I hate watching soccer.","jp":"サッカーを見るのが嫌いです。","cat":"part1"},{"en":"I’m not really into soccer.","jp":"サッカーにはあまり興味がありません。","cat":"part1"},{"en":"I saw it on Instagram.","jp":"インスタで見ました。","cat":"part1"},{"en":"I saw it in the comments.","jp":"コメント欄の中で見ました。","cat":"part1"}],"legacyId":"q11","section":"Original Review","isOriginal":true}'::jsonb, true, 6),
    ('july-06', 'july-06-original-q12', 11, 'Original Review', 'order', '{"id":"july-06-original-q12","type":"order","cat":"builder","prompt":{"en":"Sentence Builder: Make 「今日はまだお酒を飲んでいません。」","jp":"文を組み立てましょう：「今日はまだお酒を飲んでいません。」"},"words":["had","I","any alcohol","yet today","haven’t"],"correctOrder":[1,4,0,2,3],"hint":{"en":"Start with I haven’t...","jp":"I haven’t... から始めます。"},"explanation":{"en":"The sentence is “I haven’t had any alcohol yet today.”","jp":"自然な文は “I haven’t had any alcohol yet today.” です。"},"legacyId":"q12","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q13', 12, 'Original Review', 'order', '{"id":"july-06-original-q13","type":"order","cat":"builder","prompt":{"en":"Sentence Builder: Make 「サッカーを見るのが嫌いです。」","jp":"文を組み立てましょう：「サッカーを見るのが嫌いです。」"},"words":["soccer","hate","I","watching"],"correctOrder":[2,1,3,0],"hint":{"en":"hate + watching.","jp":"hate + watching です。"},"explanation":{"en":"The sentence is “I hate watching soccer.”","jp":"自然な文は “I hate watching soccer.” です。"},"legacyId":"q13","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q14', 13, 'Original Review', 'order', '{"id":"july-06-original-q14","type":"order","cat":"builder","prompt":{"en":"Sentence Builder: Make 「インスタで見ました。」","jp":"文を組み立てましょう：「インスタで見ました。」"},"words":["on Instagram","it","I","saw"],"correctOrder":[2,3,1,0],"hint":{"en":"SNS uses on.","jp":"SNSには on を使います。"},"explanation":{"en":"The sentence is “I saw it on Instagram.”","jp":"自然な文は “I saw it on Instagram.” です。"},"legacyId":"q14","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q15', 14, 'Original Review', 'situation', '{"id":"july-06-original-q15","type":"situation","cat":"sparkle","prompt":{"en":"Which word sounds natural for cute shiny accessories?","jp":"かわいいアクセサリーがキラキラしている時、自然なのはどれですか？"},"choices":[{"id":"a","en":"sparkly","jp":"キラキラしている。アクセサリーなどに自然。"},{"id":"b","en":"interested","jp":"興味がある、という意味です。"},{"id":"c","en":"on behalf","jp":"代わりに、という意味です。"},{"id":"d","en":"drunk","jp":"drink の過去分詞です。"}],"correct":"a","hint":{"en":"Sparkly things are cute and shiny.","jp":"sparkly はかわいくキラキラした感じです。"},"explanation":{"en":"Use sparkly for earrings, eyes, and cute things that shine.","jp":"イヤリング、目、かわいい物のキラキラには sparkly が自然です。"},"situationQuote":{"en":"Someone has cute earrings that shine beautifully."},"legacyId":"q15","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q16', 15, 'Original Review', 'situation', '{"id":"july-06-original-q16","type":"situation","cat":"sparkle","prompt":{"en":"Which word fits best?","jp":"一番合う単語はどれですか？"},"choices":[{"id":"a","en":"glittery","jp":"ラメっぽくキラキラしている。"},{"id":"b","en":"shiny","jp":"ピカピカですが、ラメ感は弱いです。"},{"id":"c","en":"interested","jp":"興味がある、なので違います。"},{"id":"d","en":"behalf","jp":"代わりに、なので違います。"}],"correct":"a","hint":{"en":"Glitter = ラメ.","jp":"glitter = ラメです。"},"explanation":{"en":"Use glittery for nails, makeup, dresses, or things with glitter.","jp":"ネイル、メイク、服などのラメっぽいキラキラには glittery を使います。"},"situationQuote":{"en":"Her nails have glitter / ラメ."},"legacyId":"q16","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q17', 16, 'Original Review', 'situation', '{"id":"july-06-original-q17","type":"situation","cat":"sparkle","prompt":{"en":"Which word is best for ピカピカ?","jp":"車がピカピカしている時、一番合う単語はどれですか？"},"choices":[{"id":"a","en":"shiny","jp":"ピカピカ / ツヤツヤ。車・靴・髪に自然。"},{"id":"b","en":"glittery","jp":"ラメっぽい感じです。"},{"id":"c","en":"sparkle","jp":"動詞として「キラキラ光る」。ここでは shiny が自然。"},{"id":"d","en":"drank","jp":"drink の過去形です。"}],"correct":"a","hint":{"en":"Clean cars, shoes, metal, and hair can be shiny.","jp":"車、靴、金属、髪は shiny が自然です。"},"explanation":{"en":"“The car is shiny” means the car looks clean and bright.","jp":"“The car is shiny.” は「車がピカピカ」という意味です。"},"situationQuote":{"en":"A car is very clean and bright."},"legacyId":"q17","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q18', 17, 'Original Review', 'mcq', '{"id":"july-06-original-q18","type":"mcq","cat":"sparkle","prompt":{"en":"True or False: “sparkling water” usually means ラメの水.","jp":"True or False：“sparkling water” は普通「ラメの水」という意味です。"},"choices":[{"id":"a","en":"True","jp":"正しい"},{"id":"b","en":"False","jp":"違う"}],"correct":"b","hint":{"en":"Sparkling water is carbonated water.","jp":"sparkling water は炭酸水です。"},"explanation":{"en":"“Sparkling water” usually means carbonated water, not glittery water.","jp":"“sparkling water” は普通「炭酸水」の意味です。"},"legacyId":"q18","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q19', 18, 'Original Review', 'situation', '{"id":"july-06-original-q19","type":"situation","cat":"interest","prompt":{"en":"Which sentence is correct?","jp":"「英語に興味があります」と言いたい時、正しい文はどれですか？"},"choices":[{"id":"a","en":"I’m interested in English.","jp":"英語に興味があります。"},{"id":"b","en":"I’m interesting in English.","jp":"意味が変わって不自然です。"},{"id":"c","en":"English is interested me.","jp":"文法が不自然です。"},{"id":"d","en":"I interest English.","jp":"この形は不自然です。"}],"correct":"a","hint":{"en":"Your feeling = interested.","jp":"自分の気持ちは interested です。"},"explanation":{"en":"Use interested for a person’s feeling: I’m interested in English.","jp":"人の気持ちには interested を使います。"},"situationQuote":{"en":"You want to say you have interest in English."},"legacyId":"q19","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q20', 19, 'Original Review', 'mcq', '{"id":"july-06-original-q20","type":"mcq","cat":"interest","prompt":{"en":"Which sentence means 「それは面白いです / 興味深いです」?","jp":"「それは面白いです / 興味深いです」はどれですか？"},"choices":[{"id":"a","en":"It’s interesting.","jp":"それは面白いです / 興味深いです。"},{"id":"b","en":"It’s interested.","jp":"物が興味を持っているように聞こえて不自然です。"},{"id":"c","en":"I’m interesting in it.","jp":"意味・形が違います。"},{"id":"d","en":"It interests in me.","jp":"不自然です。"}],"correct":"a","hint":{"en":"Thing/story = interesting.","jp":"物・話は interesting です。"},"explanation":{"en":"Use interesting for the thing that creates interest.","jp":"興味を引く物・話には interesting を使います。"},"legacyId":"q20","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q21', 20, 'Original Review', 'mcq', '{"id":"july-06-original-q21","type":"mcq","cat":"interest","prompt":{"en":"Mistake Detective: Which sentence is dangerous if you mean 「私は興味があります」?","jp":"ミス発見：「私は興味があります」と言いたい時、意味が変わる危険な文はどれですか？"},"choices":[{"id":"a","en":"I’m interesting.","jp":"私は面白い人です、という意味になります。"},{"id":"b","en":"I’m interested.","jp":"私は興味があります。"},{"id":"c","en":"I’m interested in English.","jp":"英語に興味があります。"},{"id":"d","en":"That story is interesting.","jp":"その話は面白いです。"}],"correct":"a","hint":{"en":"-ed is feeling. -ing causes the feeling.","jp":"-ed は気持ち、-ing はその気持ちを起こすものです。"},"explanation":{"en":"“I’m interesting” means “I am an interesting person,” not “I am interested.”","jp":"“I’m interesting.” は「私は面白い人です」という意味です。"},"legacyId":"q21","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q22', 21, 'Original Review', 'situation', '{"id":"july-06-original-q22","type":"situation","cat":"behalf","prompt":{"en":"Which sentence is natural?","jp":"自然な文はどれですか？"},"choices":[{"id":"a","en":"Can you reply on my behalf?","jp":"私の代わりに返信してくれますか？"},{"id":"b","en":"Can you reply behalf of me?","jp":"不自然です。"},{"id":"c","en":"Can you reply in my behalf?","jp":"前置詞が違います。"},{"id":"d","en":"Can you reply my behalf?","jp":"on が必要です。"}],"correct":"a","hint":{"en":"Use on my behalf.","jp":"on my behalf を使います。"},"explanation":{"en":"“On my behalf” means someone does something for you or represents you.","jp":"“on my behalf” は「私の代わりに / 私を代表して」という意味です。"},"situationQuote":{"en":"You cannot reply, so you ask someone to reply for you."},"legacyId":"q22","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q23', 22, 'Original Review', 'mcq', '{"id":"july-06-original-q23","type":"mcq","cat":"behalf","prompt":{"en":"Which phrase is more natural than “behalf of me”?","jp":"“behalf of me” より自然なのはどれですか？"},"choices":[{"id":"a","en":"on my behalf","jp":"私の代わりに。自然です。"},{"id":"b","en":"at my behalf","jp":"不自然です。"},{"id":"c","en":"in my behalf","jp":"不自然です。"},{"id":"d","en":"by my behalf","jp":"不自然です。"}],"correct":"a","hint":{"en":"The natural phrase is on my behalf.","jp":"自然な表現は on my behalf です。"},"explanation":{"en":"Say “on my behalf,” not “behalf of me.”","jp":"“behalf of me” ではなく “on my behalf” が自然です。"},"legacyId":"q23","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q24', 23, 'Original Review', 'mcq', '{"id":"july-06-original-q24","type":"mcq","cat":"behalf","prompt":{"en":"Which sentence sounds like a formal representative phrase?","jp":"代表して話すフォーマルな表現はどれですか？"},"choices":[{"id":"a","en":"I’m speaking on behalf of the team.","jp":"チームを代表して話しています。"},{"id":"b","en":"I’m speaking on the team behalf me.","jp":"語順が不自然です。"},{"id":"c","en":"I’m interesting on the team.","jp":"意味が違います。"},{"id":"d","en":"I saw it on behalf.","jp":"意味が違います。"}],"correct":"a","hint":{"en":"on behalf of + person/group.","jp":"on behalf of + 人・団体です。"},"explanation":{"en":"“On behalf of the team” means representing the team.","jp":"“on behalf of the team” は「チームを代表して」という意味です。"},"legacyId":"q24","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q25', 24, 'Original Review', 'matching', '{"id":"july-06-original-q25","type":"matching","cat":"part2","prompt":{"en":"Part 2 Match: Match each nuance word with its Japanese meaning.","jp":"Part 2 マッチ：各ニュアンス単語と日本語の意味を合わせましょう。"},"hint":{"en":"Think about the situation where each word is used.","jp":"それぞれの単語が使われる場面を考えましょう。"},"pairs":[{"en":"sparkly","jp":"キラキラしている。アクセサリーや目など。","cat":"part2"},{"en":"glittery","jp":"ラメっぽくキラキラしている。","cat":"part2"},{"en":"shiny","jp":"ピカピカ / ツヤツヤ。","cat":"part2"},{"en":"interested","jp":"興味がある。人の気持ち。","cat":"part2"},{"en":"interesting","jp":"面白い / 興味深い。物や話。","cat":"part2"},{"en":"on my behalf","jp":"私の代わりに / 私を代表して。","cat":"part2"}],"legacyId":"q25","section":"Original Review","isOriginal":true}'::jsonb, true, 6),
    ('july-06', 'july-06-original-q26', 25, 'Original Review', 'order', '{"id":"july-06-original-q26","type":"order","cat":"builder","prompt":{"en":"Sentence Builder: Make 「英語に興味があります。」","jp":"文を組み立てましょう：「英語に興味があります。」"},"words":["interested","English","I’m","in"],"correctOrder":[2,0,3,1],"hint":{"en":"Feeling = interested in...","jp":"気持ちは interested in... です。"},"explanation":{"en":"The sentence is “I’m interested in English.”","jp":"自然な文は “I’m interested in English.” です。"},"legacyId":"q26","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q27', 26, 'Original Review', 'order', '{"id":"july-06-original-q27","type":"order","cat":"builder","prompt":{"en":"Sentence Builder: Make 「私の代わりに返信してくれますか？」","jp":"文を組み立てましょう：「私の代わりに返信してくれますか？」"},"words":["reply","on my behalf","Can","you"],"correctOrder":[2,3,0,1],"hint":{"en":"Use Can you...","jp":"Can you... から始めます。"},"explanation":{"en":"The sentence is “Can you reply on my behalf?”","jp":"自然な文は “Can you reply on my behalf?” です。"},"legacyId":"q27","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q28', 27, 'Original Review', 'typing', '{"id":"july-06-original-q28","type":"typing","cat":"alcohol","promptJP":"今日はまだお酒を飲んでいません。","accepted":["I haven''t had any alcohol yet today","I have not had any alcohol yet today","I haven''t had alcohol yet today"],"hint":{"en":"Use haven’t had any alcohol yet today.","jp":"haven’t had any alcohol yet today を使います。"},"explanation":{"en":"This is the most natural daily sentence.","jp":"日常ではこの文がとても自然です。"},"legacyId":"q28","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q29', 28, 'Original Review', 'typing', '{"id":"july-06-original-q29","type":"typing","cat":"hate","promptJP":"サッカーを見るのが嫌いです。","accepted":["I hate watching soccer","I hate watching football","I don''t like watching soccer","I do not like watching soccer"],"hint":{"en":"Use hate + watching.","jp":"hate + watching を使います。"},"explanation":{"en":"“I don’t like watching soccer” is a softer accepted version.","jp":"“I don’t like watching soccer.” はやわらかい言い方です。"},"legacyId":"q29","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q30', 29, 'Original Review', 'typing', '{"id":"july-06-original-q30","type":"typing","cat":"prepositions","promptJP":"インスタで見ました。","accepted":["I saw it on Instagram","I saw that on Instagram"],"hint":{"en":"Use on Instagram.","jp":"on Instagram を使います。"},"explanation":{"en":"For SNS platforms, use on.","jp":"SNSには on を使います。"},"legacyId":"q30","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q31', 30, 'Original Review', 'typing', '{"id":"july-06-original-q31","type":"typing","cat":"sparkle","promptJP":"キラキラしたものが好きです。","accepted":["I like sparkly things","I like sparkling things"],"hint":{"en":"For cute shiny things, use sparkly.","jp":"かわいいキラキラには sparkly が自然です。"},"explanation":{"en":"“I like sparkly things” is natural and easy.","jp":"“I like sparkly things.” は自然で使いやすいです。"},"legacyId":"q31","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q32', 31, 'Original Review', 'typing', '{"id":"july-06-original-q32","type":"typing","cat":"interest","promptJP":"英語に興味があります。","accepted":["I''m interested in English","I am interested in English"],"hint":{"en":"Your feeling = interested in.","jp":"自分の気持ちは interested in です。"},"explanation":{"en":"Use interested for your feeling.","jp":"自分の気持ちには interested を使います。"},"legacyId":"q32","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q33', 32, 'Original Review', 'typing', '{"id":"july-06-original-q33","type":"typing","cat":"interest","promptJP":"それは面白いです。","accepted":["It''s interesting","It is interesting","That''s interesting","That is interesting"],"hint":{"en":"Thing/story = interesting.","jp":"物・話は interesting です。"},"explanation":{"en":"Use interesting for the thing or story.","jp":"物や話には interesting を使います。"},"legacyId":"q33","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-original-q34', 33, 'Original Review', 'typing', '{"id":"july-06-original-q34","type":"typing","cat":"behalf","promptJP":"私の代わりに返信してくれますか？","accepted":["Can you reply on my behalf","Could you reply on my behalf","Please reply on my behalf"],"hint":{"en":"Use on my behalf.","jp":"on my behalf を使います。"},"explanation":{"en":"“Can you reply on my behalf?” is natural.","jp":"“Can you reply on my behalf?” が自然です。"},"legacyId":"q34","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('july-06', 'july-06-extra-listen-choice-1', 34, 'Listen & Speak', 'listenChoice', '{"id":"july-06-extra-listen-choice-1","format":"listenChoice","type":"listenChoice","section":"Listen & Speak","topic":"clarification","isOriginal":false,"hint":"聞き返す丁寧な表現。","hintJa":"聞き返す丁寧な表現。","explanation":"聞き返す丁寧な表現。","explanationJa":"聞き返す丁寧な表現。","prompt":"Listen and choose the sentence you hear.","promptJa":"音声を聞いて、聞こえた英文を選んでください。","audioText":"Could you say that again?","choices":[{"id":"a","en":"Could you say that again?","jp":"もう一度言っていただけますか？"},{"id":"b","en":"What do you mean?","jp":"どういう意味ですか？"},{"id":"c","en":"I’m getting used to it.","jp":"だんだん慣れてきました。"},{"id":"d","en":"I’ve never tried that before.","jp":"それは今まで試したことがありません。"}],"correct":"a"}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-listen-choice-2', 35, 'Listen & Speak', 'listenChoice', '{"id":"july-06-extra-listen-choice-2","format":"listenChoice","type":"listenChoice","section":"Listen & Speak","topic":"clarification","isOriginal":false,"hint":"意味を確認する。","hintJa":"意味を確認する。","explanation":"意味を確認する。","explanationJa":"意味を確認する。","prompt":"Listen and choose the sentence you hear.","promptJa":"音声を聞いて、聞こえた英文を選んでください。","audioText":"What do you mean?","choices":[{"id":"a","en":"What do you mean?","jp":"どういう意味ですか？"},{"id":"b","en":"I’m getting used to it.","jp":"だんだん慣れてきました。"},{"id":"c","en":"I’ve never tried that before.","jp":"それは今まで試したことがありません。"},{"id":"d","en":"It was better than I expected.","jp":"思っていたより良かったです。"}],"correct":"a"}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-dictation-1', 36, 'Listen & Speak', 'listenType', '{"id":"july-06-extra-dictation-1","format":"listenType","type":"listenType","section":"Listen & Speak","topic":"change","isOriginal":false,"hint":"get used to + 名詞。","hintJa":"get used to + 名詞。","explanation":"get used to + 名詞。","explanationJa":"get used to + 名詞。","prompt":"Type the complete sentence you hear.","promptJa":"聞こえた英文をそのまま入力してください。","audioText":"I’m getting used to it.","accepted":["I’m getting used to it."]}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-dictation-2', 37, 'Listen & Speak', 'listenType', '{"id":"july-06-extra-dictation-2","format":"listenType","type":"listenType","section":"Listen & Speak","topic":"experience","isOriginal":false,"hint":"現在完了の経験。","hintJa":"現在完了の経験。","explanation":"現在完了の経験。","explanationJa":"現在完了の経験。","prompt":"Type the complete sentence you hear.","promptJa":"聞こえた英文をそのまま入力してください。","audioText":"I’ve never tried that before.","accepted":["I’ve never tried that before."]}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-speaking-1', 38, 'Listen & Speak', 'speaking', '{"id":"july-06-extra-speaking-1","format":"speaking","type":"speaking","section":"Listen & Speak","topic":"comparisons","isOriginal":false,"hint":"better than expected。","hintJa":"better than expected。","explanation":"better than expected。","explanationJa":"better than expected。","prompt":"Listen, then say the sentence naturally.","promptJa":"音声を聞いてから、自然に言ってみましょう。","speakText":"It was better than I expected.","speakJa":"思っていたより良かったです。"}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-speaking-2', 39, 'Listen & Speak', 'speaking', '{"id":"july-06-extra-speaking-2","format":"speaking","type":"speaking","section":"Listen & Speak","topic":"learning","isOriginal":false,"hint":"説明を具体化する質問。","hintJa":"説明を具体化する質問。","explanation":"説明を具体化する質問。","explanationJa":"説明を具体化する質問。","prompt":"Listen, then say the sentence naturally.","promptJa":"音声を聞いてから、自然に言ってみましょう。","speakText":"Can you give me an example?","speakJa":"例を一つ教えてもらえますか？"}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-true-false', 40, 'Use It', 'truefalse', '{"id":"july-06-extra-true-false","format":"truefalse","type":"truefalse","section":"Use It","topic":"work","isOriginal":false,"hint":"その場で分からない時。","hintJa":"その場で分からない時。","explanation":"その場で分からない時。","explanationJa":"その場で分からない時。","prompt":"“I’ll check and let you know.” means “確認してお知らせします。”.","promptJa":"「I’ll check and let you know.」は「確認してお知らせします。」という意味です。","correct":true}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-order', 41, 'Use It', 'order', '{"id":"july-06-extra-order","format":"order","type":"order","section":"Use It","topic":"learning","isOriginal":false,"hint":"苦手な箇所を説明する。","hintJa":"苦手な箇所を説明する。","explanation":"苦手な箇所を説明する。","explanationJa":"苦手な箇所を説明する。","prompt":"Put the words in order: そこが難しいと感じる部分です。","promptJa":"語順を並べましょう：そこが難しいと感じる部分です。","words":["I","find","difficult","That’s","the","part"],"correctWords":["That’s","the","part","I","find","difficult"]}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-matching', 42, 'Use It', 'matching', '{"id":"july-06-extra-matching","format":"matching","type":"matching","section":"Use It","topic":"clarification","isOriginal":false,"hint":"聞き返す丁寧な表現。","hintJa":"聞き返す丁寧な表現。","explanation":"聞き返す丁寧な表現。","explanationJa":"聞き返す丁寧な表現。","prompt":"Match each English phrase with its natural Japanese meaning.","promptJa":"英文と自然な日本語を組み合わせてください。","pairs":[{"en":"Could you say that again?","jp":"もう一度言っていただけますか？","cat":"clarification"},{"en":"What do you mean?","jp":"どういう意味ですか？","cat":"clarification"},{"en":"I’m getting used to it.","jp":"だんだん慣れてきました。","cat":"change"},{"en":"I’ve never tried that before.","jp":"それは今まで試したことがありません。","cat":"experience"},{"en":"It was better than I expected.","jp":"思っていたより良かったです。","cat":"comparisons"},{"en":"Can you give me an example?","jp":"例を一つ教えてもらえますか？","cat":"learning"}]}'::jsonb, false, 6),
    ('july-06', 'july-06-extra-sorting', 43, 'Use It', 'sorting', '{"id":"july-06-extra-sorting","format":"sorting","type":"sorting","section":"Use It","topic":"clarification","isOriginal":false,"hint":"意味を確認する。","hintJa":"意味を確認する。","explanation":"意味を確認する。","explanationJa":"意味を確認する。","prompt":"Sort each phrase by its language purpose.","promptJa":"各表現を目的別に分類してください。","categories":["clarification","change"],"items":[["Could you say that again?","clarification"],["What do you mean?","clarification"],["I’m getting used to it.","change"]]}'::jsonb, false, 3),
    ('july-06', 'july-06-extra-dialogue', 44, 'Use It', 'dialogue', '{"id":"july-06-extra-dialogue","format":"dialogue","type":"dialogue","section":"Use It","topic":"clarification","isOriginal":false,"hint":"意味を確認する。","hintJa":"意味を確認する。","explanation":"意味を確認する。","explanationJa":"意味を確認する。","prompt":"Choose the most natural next line in the conversation.","promptJa":"会話の次に続く最も自然な一文を選んでください。","context":"A: This part is a little abstract.\nB: ...","contextJa":"A：「この部分は少し抽象的です。」\nB：…","choices":[{"id":"a","en":"What do you mean?","jp":"どういう意味ですか？"},{"id":"b","en":"I’m getting used to it.","jp":"だんだん慣れてきました。"},{"id":"c","en":"I’ve never tried that before.","jp":"それは今まで試したことがありません。"},{"id":"d","en":"It was better than I expected.","jp":"思っていたより良かったです。"}],"correct":"a"}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-translation', 45, 'Use It', 'translation', '{"id":"july-06-extra-translation","format":"translation","type":"translation","section":"Use It","topic":"change","isOriginal":false,"hint":"get used to + 名詞。","hintJa":"get used to + 名詞。","explanation":"get used to + 名詞。","explanationJa":"get used to + 名詞。","prompt":"Translate into English: だんだん慣れてきました。","promptJa":"英語にしてください：だんだん慣れてきました。","accepted":["I’m getting used to it."]}'::jsonb, false, 1),
    ('july-06', 'july-06-extra-situation', 46, 'Use It', 'situation', '{"id":"july-06-extra-situation","format":"situation","type":"situation","section":"Use It","topic":"experience","isOriginal":false,"hint":"現在完了の経験。","hintJa":"現在完了の経験。","explanation":"現在完了の経験。","explanationJa":"現在完了の経験。","prompt":"Which sentence best expresses this meaning: それは今まで試したことがありません。","promptJa":"「それは今まで試したことがありません。」に最も合う英文はどれですか？","choices":[{"id":"a","en":"I’ve never tried that before.","jp":"それは今まで試したことがありません。"},{"id":"b","en":"It was better than I expected.","jp":"思っていたより良かったです。"},{"id":"c","en":"Can you give me an example?","jp":"例を一つ教えてもらえますか？"},{"id":"d","en":"I’ll check and let you know.","jp":"確認してお知らせします。"}],"correct":"a"}'::jsonb, false, 1),
    ('june-28', 'june-28-original-q1', 0, 'Original Review', 'mcq', '{"id":"june-28-original-q1","type":"mcq","cat":"wouldLike","prompt":{"en":"Warm-up: Which sentence is the most polite way to ask 「何を飲みたいですか？」?","jp":"ウォームアップ：「何を飲みたいですか？」を一番丁寧で自然に聞く英語はどれですか？"},"choices":[{"id":"a","en":"What would you like to drink?","jp":"何を飲みたいですか？"},{"id":"b","en":"What do you drink?","jp":"普段何を飲みますか？"},{"id":"c","en":"What are you drink?","jp":"文法的に不自然です。"},{"id":"d","en":"What you like drink?","jp":"語順が不自然です。"}],"correct":"a","hint":{"en":"Use “would like” when you want to sound polite.","jp":"丁寧に聞きたいときは would like を使います。"},"explanation":{"en":"“What would you like to drink?” is polite and natural in a café, restaurant, or lesson conversation.","jp":"“What would you like to drink?” はカフェ・レストラン・レッスン会話で自然で丁寧な聞き方です。"},"legacyId":"q1","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q2', 1, 'Original Review', 'situation', '{"id":"june-28-original-q2","type":"situation","cat":"wouldLike","situationQuote":{"en":"Café staff: “What would you like to eat?”"},"prompt":{"en":"Café Mission: Choose the best reply.","jp":"カフェミッション：一番自然な返事を選びましょう。"},"choices":[{"id":"a","en":"I’d like pasta, please.","jp":"パスタがいいです。"},{"id":"b","en":"I like eat pasta.","jp":"文法的に不自然です。"},{"id":"c","en":"I would pasta, please.","jp":"like が必要です。"},{"id":"d","en":"Pasta is drink.","jp":"意味が変です。"}],"correct":"a","hint":{"en":"The answer can use the same polite pattern: “I’d like...”.","jp":"答えも同じ丁寧な形 “I’d like...” を使えます。"},"explanation":{"en":"“I’d like pasta, please” sounds polite and natural when ordering food.","jp":"注文するときは “I’d like pasta, please.” が丁寧で自然です。"},"legacyId":"q2","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q3', 2, 'Original Review', 'mcq', '{"id":"june-28-original-q3","type":"mcq","cat":"wouldLike","prompt":{"en":"TRUE or FALSE: “I like coffee” and “I’d like coffee” mean exactly the same thing.","jp":"○×問題：“I like coffee” と “I’d like coffee” はまったく同じ意味です。"},"choices":[{"id":"t","en":"True","jp":"正しい"},{"id":"f","en":"False","jp":"違います"}],"correct":"f","hint":{"en":"One is about general preference. One is about what you want now.","jp":"一つは普段の好み。もう一つは今ほしいものです。"},"explanation":{"en":"“I like coffee” means coffee is your preference. “I’d like coffee” means you want coffee now.","jp":"“I like coffee.” は「コーヒーが好き」。 “I’d like coffee.” は「今コーヒーがほしい・コーヒーがいい」です。"},"legacyId":"q3","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q4', 3, 'Original Review', 'situation', '{"id":"june-28-original-q4","type":"situation","cat":"turnTaking","situationQuote":{"en":"A: “I’d like tea.”  B: “...”"},"prompt":{"en":"Mini Dialogue: B wants to ask A the same question back. What should B say?","jp":"ミニ会話：Bが相手にも同じ質問を返したいです。何と言えばいいですか？"},"choices":[{"id":"a","en":"How about you?","jp":"あなたはどうですか？"},{"id":"b","en":"Who will win?","jp":"誰が勝つ？"},{"id":"c","en":"It can’t be helped.","jp":"仕方ない。"},{"id":"d","en":"Did he help you?","jp":"彼は手伝いましたか？"}],"correct":"a","hint":{"en":"This phrase is perfect after you answer someone’s question.","jp":"自分が答えたあとに、相手へ聞き返すときの表現です。"},"explanation":{"en":"“How about you?” keeps the conversation moving naturally after you answer.","jp":"“How about you?” は、自分が答えたあとに「あなたは？」と自然に会話を続ける表現です。"},"legacyId":"q4","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q5', 4, 'Original Review', 'mcq', '{"id":"june-28-original-q5","type":"mcq","cat":"wouldLike","prompt":{"en":"Mistake Detective: What is wrong with “I would coffee”?","jp":"間違い探し：“I would coffee” は何が足りませんか？"},"choices":[{"id":"a","en":"It needs “like”: I would like coffee.","jp":"like が必要です：I would like coffee."},{"id":"b","en":"It needs “win”: I would win coffee.","jp":"win は必要ありません。"},{"id":"c","en":"It needs “did”: I did would coffee.","jp":"did は必要ありません。"},{"id":"d","en":"Nothing is wrong.","jp":"間違いはありません。"}],"correct":"a","hint":{"en":"The full phrase is “would like.”","jp":"セットで “would like” です。"},"explanation":{"en":"Use “would like” together. “I would coffee” is incomplete.","jp":"“would like” はセットです。“I would coffee.” だけだと不完全です。"},"legacyId":"q5","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q6', 5, 'Original Review', 'mcq', '{"id":"june-28-original-q6","type":"mcq","cat":"pastQuestions","prompt":{"en":"Speed Check: Which past question is correct?","jp":"スピードチェック：正しい過去の質問はどれですか？"},"choices":[{"id":"a","en":"Did he help you yesterday?","jp":"彼は昨日あなたを手伝いましたか？"},{"id":"b","en":"Did he helped you yesterday?","jp":"Did の後は helped ではなく help です。"},{"id":"c","en":"Helped he you yesterday?","jp":"語順が不自然です。"},{"id":"d","en":"Did he helps you yesterday?","jp":"helps ではなく help です。"}],"correct":"a","hint":{"en":"After “Did,” use the base verb.","jp":"Did の後は動詞の原形です。"},"explanation":{"en":"Past questions use “Did + subject + base verb?” so the correct sentence is “Did he help you yesterday?”","jp":"過去の質問は “Did + 主語 + 動詞の原形？” なので “Did he help you yesterday?” が正解です。"},"legacyId":"q6","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q7', 6, 'Original Review', 'mcq', '{"id":"june-28-original-q7","type":"mcq","cat":"pastQuestions","prompt":{"en":"TRUE or FALSE: After “Did,” we usually use the past verb like “helped.”","jp":"○×問題：Did の後は、ふつう helped のような過去形を使います。"},"choices":[{"id":"t","en":"True","jp":"正しい"},{"id":"f","en":"False","jp":"違います"}],"correct":"f","hint":{"en":"Did already shows the past.","jp":"Did がもう過去を表しています。"},"explanation":{"en":"Because “Did” already marks the sentence as past, the main verb returns to the base form: help, eat, call.","jp":"Did が過去を表すので、メインの動詞は原形になります：help / eat / call。"},"legacyId":"q7","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q8', 7, 'Original Review', 'situation', '{"id":"june-28-original-q8","type":"situation","cat":"pastQuestions","situationQuote":{"en":"Bad sentence: “Did he helped you yesterday?”"},"prompt":{"en":"Fix-It Challenge: Choose the corrected sentence.","jp":"修正チャレンジ：正しく直した文を選びましょう。"},"choices":[{"id":"a","en":"Did he help you yesterday?","jp":"彼は昨日あなたを手伝いましたか？"},{"id":"b","en":"Did he helping you yesterday?","jp":"不自然です。"},{"id":"c","en":"Did helped he you yesterday?","jp":"語順が不自然です。"},{"id":"d","en":"He did helped yesterday?","jp":"不自然です。"}],"correct":"a","hint":{"en":"Remove the -ed after Did.","jp":"Did の後の -ed を外します。"},"explanation":{"en":"The corrected sentence is “Did he help you yesterday?” because the verb after Did is the base form.","jp":"正しくは “Did he help you yesterday?” です。Did の後は動詞の原形です。"},"legacyId":"q8","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q9', 8, 'Original Review', 'situation', '{"id":"june-28-original-q9","type":"situation","cat":"winning","situationQuote":{"en":"You are watching Japan vs Brazil with a friend."},"prompt":{"en":"Stadium Question: What is the most natural way to ask 「どっちが勝つと思う？」?","jp":"スタジアム問題：「どっちが勝つと思う？」を自然に聞く英語はどれですか？"},"choices":[{"id":"a","en":"Who will win, Japan or Brazil?","jp":"日本とブラジル、どちらが勝つと思う？"},{"id":"b","en":"Who will winning Japan or Brazil?","jp":"文法的に不自然です。"},{"id":"c","en":"Who win will Japan or Brazil?","jp":"語順が不自然です。"},{"id":"d","en":"Japan or Brazil who?","jp":"不自然です。"}],"correct":"a","hint":{"en":"Use “will + base verb.”","jp":"will + 動詞の原形を使います。"},"explanation":{"en":"“Who will win, Japan or Brazil?” is natural when asking about teams, countries, or players.","jp":"チーム・国・選手の勝敗を聞くときは “Who will win, Japan or Brazil?” が自然です。"},"legacyId":"q9","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q10', 9, 'Original Review', 'mcq', '{"id":"june-28-original-q10","type":"mcq","cat":"winning","prompt":{"en":"TRUE or FALSE: “Who will win, Japan or Brazil?” can sound natural even though Japan and Brazil are countries.","jp":"○×問題：“Who will win, Japan or Brazil?” は、Japan と Brazil が国でも自然に聞こえることがあります。"},"choices":[{"id":"t","en":"True","jp":"正しい"},{"id":"f","en":"False","jp":"違います"}],"correct":"t","hint":{"en":"In sports, countries often mean the teams.","jp":"スポーツでは国名がチームを表すことが多いです。"},"explanation":{"en":"In sports conversations, “Japan” and “Brazil” often mean the teams, so “Who will win?” sounds natural.","jp":"スポーツの会話では Japan / Brazil がチームを表すので、“Who will win?” は自然です。"},"legacyId":"q10","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q11', 10, 'Original Review', 'mcq', '{"id":"june-28-original-q11","type":"mcq","cat":"winning","prompt":{"en":"Nuance Check: Which one clearly means 「どちらのチームが勝ちますか？」?","jp":"ニュアンスチェック：「どちらのチームが勝ちますか？」をはっきり言うならどれですか？"},"choices":[{"id":"a","en":"Which team will win?","jp":"どちらのチームが勝ちますか？"},{"id":"b","en":"Which team will help?","jp":"どちらのチームが手伝いますか？"},{"id":"c","en":"How about you?","jp":"あなたはどう？"},{"id":"d","en":"It can’t be helped.","jp":"仕方ない。"}],"correct":"a","hint":{"en":"If you want to be very clear, use “team.”","jp":"はっきりチームと言いたいなら team を使います。"},"explanation":{"en":"“Which team will win?” is clear and slightly more specific than “Who will win?”","jp":"“Which team will win?” は “Who will win?” より少しはっきり「チーム」を意識した言い方です。"},"legacyId":"q11","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q12', 11, 'Original Review', 'situation', '{"id":"june-28-original-q12","type":"situation","cat":"cantBeHelped","situationQuote":{"en":"The train already left. You cannot change it now."},"prompt":{"en":"Real-Life Reaction: What can you say?","jp":"リアルな反応：この場面で何と言えますか？"},"choices":[{"id":"a","en":"There’s nothing we can do.","jp":"もうどうしようもない。"},{"id":"b","en":"What would you like to drink?","jp":"何を飲みたいですか？"},{"id":"c","en":"How about you?","jp":"あなたは？"},{"id":"d","en":"Who will win?","jp":"誰が勝つ？"}],"correct":"a","hint":{"en":"There are no useful actions left.","jp":"もうできることがない状況です。"},"explanation":{"en":"“There’s nothing we can do” is natural when the situation cannot be changed now.","jp":"もう変えられない状況では “There’s nothing we can do.” が自然です。"},"legacyId":"q12","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q13', 12, 'Original Review', 'situation', '{"id":"june-28-original-q13","type":"situation","cat":"cantBeHelped","situationQuote":{"en":"It’s raining, so the outdoor event was cancelled."},"prompt":{"en":"Soft Acceptance: Which phrase sounds closest to 「仕方ないね」?","jp":"受け入れる一言：「仕方ないね」に一番近い英語はどれですか？"},"choices":[{"id":"a","en":"It can’t be helped.","jp":"仕方ないね。"},{"id":"b","en":"I’d like coffee.","jp":"コーヒーがいいです。"},{"id":"c","en":"Did he help you yesterday?","jp":"彼は昨日手伝いましたか？"},{"id":"d","en":"Which team will win?","jp":"どちらのチームが勝ちますか？"}],"correct":"a","hint":{"en":"This phrase accepts the situation.","jp":"状況を受け入れる感じの表現です。"},"explanation":{"en":"“It can’t be helped” is close to 「仕方ない」 and is used when you accept a situation you cannot change.","jp":"“It can’t be helped.” は「仕方ない」に近く、変えられない状況を受け入れるときに使います。"},"legacyId":"q13","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q14', 13, 'Original Review', 'mcq', '{"id":"june-28-original-q14","type":"mcq","cat":"cantBeHelped","prompt":{"en":"TRUE or FALSE: “There is nothing that can be done” is usually more casual than “There’s nothing we can do.”","jp":"○×問題：“There is nothing that can be done” は “There’s nothing we can do” よりカジュアルです。"},"choices":[{"id":"t","en":"True","jp":"正しい"},{"id":"f","en":"False","jp":"違います"}],"correct":"f","hint":{"en":"Longer often sounds more formal here.","jp":"この場合、長い表現は少し硬く聞こえやすいです。"},"explanation":{"en":"“There is nothing that can be done” is correct, but it sounds more formal. In daily speech, “There’s nothing we can do” is usually more natural.","jp":"“There is nothing that can be done.” は正しいですが少し硬いです。日常会話では “There’s nothing we can do.” の方が自然です。"},"legacyId":"q14","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q15', 14, 'Original Review', 'situation', '{"id":"june-28-original-q15","type":"situation","cat":"reasonWith","situationQuote":{"en":"He was angry, so I tried to talk calmly and make him understand."},"prompt":{"en":"Phrase Hunter: Which sentence fits this situation?","jp":"フレーズ探し：この状況に合う英文はどれですか？"},"choices":[{"id":"a","en":"I tried to reason with him.","jp":"彼を説得しようとした / 理性的に話そうとした。"},{"id":"b","en":"I tried to win with him.","jp":"彼と勝とうとした。意味が違います。"},{"id":"c","en":"I tried to drink with him.","jp":"彼と飲もうとした。意味が違います。"},{"id":"d","en":"I tried to helped him.","jp":"文法的に不自然です。"}],"correct":"a","hint":{"en":"This phrase means to talk calmly and persuade someone.","jp":"落ち着いて話して説得するイメージです。"},"explanation":{"en":"“Reason with someone” means to talk calmly and try to persuade them, especially when they are upset or emotional.","jp":"“reason with someone” は、相手が怒っている・感情的なときに、落ち着いて話して説得しようとする意味です。"},"legacyId":"q15","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q16', 15, 'Original Review', 'matching', '{"id":"june-28-original-q16","type":"matching","cat":"mixed","prompt":{"en":"Speed Match: Connect each phrase to the Japanese meaning.","jp":"スピードマッチ：英語フレーズと日本語の意味をつなげましょう。"},"hint":{"en":"Match meaning, not word order.","jp":"単語の順番ではなく、意味でマッチしましょう。"},"pairs":[{"en":"What would you like to drink?","jp":"何を飲みたいですか？","cat":"wouldLike"},{"en":"I’d like coffee.","jp":"コーヒーがいいです。","cat":"wouldLike"},{"en":"How about you?","jp":"あなたはどうですか？","cat":"turnTaking"},{"en":"Did he help you yesterday?","jp":"彼は昨日あなたを手伝いましたか？","cat":"pastQuestions"},{"en":"Who will win?","jp":"誰が勝つ？ / どちらが勝つ？","cat":"winning"},{"en":"There’s nothing we can do.","jp":"もうどうしようもない。","cat":"cantBeHelped"},{"en":"It can’t be helped.","jp":"仕方ない。","cat":"cantBeHelped"},{"en":"reason with someone","jp":"人を説得する / 理性的に話す","cat":"reasonWith"}],"legacyId":"q16","section":"Original Review","isOriginal":true}'::jsonb, true, 8),
    ('june-28', 'june-28-original-q17a', 16, 'Original Review', 'typing', '{"id":"june-28-original-q17a","type":"typing","cat":"wouldLike","promptJP":"何を飲みたいですか？","accepted":["What would you like to drink"],"hint":{"en":"Start with “What would you like...”.","jp":"“What would you like...” から始めます。"},"explanation":{"en":"The natural polite question is “What would you like to drink?”","jp":"丁寧で自然な質問は “What would you like to drink?” です。"},"legacyId":"q17a","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q17b', 17, 'Original Review', 'typing', '{"id":"june-28-original-q17b","type":"typing","cat":"wouldLike","promptJP":"コーヒーがいいです。","accepted":["I''d like coffee","I would like coffee"],"hint":{"en":"Use “I’d like...” or “I would like...”.","jp":"“I’d like...” または “I would like...” を使います。"},"explanation":{"en":"“I’d like coffee” is short, polite, and natural.","jp":"“I’d like coffee.” は短くて丁寧で自然です。"},"legacyId":"q17b","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q17c', 18, 'Original Review', 'typing', '{"id":"june-28-original-q17c","type":"typing","cat":"turnTaking","promptJP":"あなたはどうですか？","accepted":["How about you"],"hint":{"en":"Three words. This phrase returns the same question.","jp":"3語です。同じ質問を相手に返す表現です。"},"explanation":{"en":"“How about you?” is a natural way to ask the same question back.","jp":"“How about you?” は「あなたは？」と自然に聞き返す表現です。"},"legacyId":"q17c","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q17d', 19, 'Original Review', 'typing', '{"id":"june-28-original-q17d","type":"typing","cat":"pastQuestions","promptJP":"彼は昨日あなたを手伝いましたか？","accepted":["Did he help you yesterday"],"hint":{"en":"Use Did + he + base verb.","jp":"Did + he + 動詞の原形を使います。"},"explanation":{"en":"“Did he help you yesterday?” uses the base verb “help” after Did.","jp":"“Did he help you yesterday?” では Did の後なので help を使います。"},"legacyId":"q17d","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-original-q17e', 20, 'Original Review', 'typing', '{"id":"june-28-original-q17e","type":"typing","cat":"cantBeHelped","promptJP":"仕方ない。","accepted":["It can''t be helped","It cannot be helped"],"hint":{"en":"Start with “It can’t...”.","jp":"“It can’t...” から始めます。"},"explanation":{"en":"“It can’t be helped” is close to 「仕方ない」 when accepting a situation.","jp":"“It can’t be helped.” は、状況を受け入れる「仕方ない」に近い表現です。"},"legacyId":"q17e","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-28', 'june-28-extra-listen-choice-1', 21, 'Listen & Speak', 'listenChoice', '{"id":"june-28-extra-listen-choice-1","format":"listenChoice","type":"listenChoice","section":"Listen & Speak","topic":"polite orders","isOriginal":false,"hint":"I’d like は丁寧な注文。","hintJa":"I’d like は丁寧な注文。","explanation":"I’d like は丁寧な注文。","explanationJa":"I’d like は丁寧な注文。","prompt":"Listen and choose the sentence you hear.","promptJa":"音声を聞いて、聞こえた英文を選んでください。","audioText":"I’d like a coffee, please.","choices":[{"id":"a","en":"I’d like a coffee, please.","jp":"コーヒーをお願いします。"},{"id":"b","en":"How about you?","jp":"あなたはどうですか？"},{"id":"c","en":"What did you order?","jp":"何を注文しましたか？"},{"id":"d","en":"It can’t be helped.","jp":"仕方ありません。"}],"correct":"a"}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-listen-choice-2', 22, 'Listen & Speak', 'listenChoice', '{"id":"june-28-extra-listen-choice-2","format":"listenChoice","type":"listenChoice","section":"Listen & Speak","topic":"follow-up questions","isOriginal":false,"hint":"相手にも同じ質問を返す。","hintJa":"相手にも同じ質問を返す。","explanation":"相手にも同じ質問を返す。","explanationJa":"相手にも同じ質問を返す。","prompt":"Listen and choose the sentence you hear.","promptJa":"音声を聞いて、聞こえた英文を選んでください。","audioText":"How about you?","choices":[{"id":"a","en":"How about you?","jp":"あなたはどうですか？"},{"id":"b","en":"What did you order?","jp":"何を注文しましたか？"},{"id":"c","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"d","en":"Could I have the menu?","jp":"メニューをいただけますか？"}],"correct":"a"}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-dictation-1', 23, 'Listen & Speak', 'listenType', '{"id":"june-28-extra-dictation-1","format":"listenType","type":"listenType","section":"Listen & Speak","topic":"past questions","isOriginal":false,"hint":"did の後は動詞の原形。","hintJa":"did の後は動詞の原形。","explanation":"did の後は動詞の原形。","explanationJa":"did の後は動詞の原形。","prompt":"Type the complete sentence you hear.","promptJa":"聞こえた英文をそのまま入力してください。","audioText":"What did you order?","accepted":["What did you order?"]}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-dictation-2', 24, 'Listen & Speak', 'listenType', '{"id":"june-28-extra-dictation-2","format":"listenType","type":"listenType","section":"Listen & Speak","topic":"useful responses","isOriginal":false,"hint":"変えられない状況への自然な反応。","hintJa":"変えられない状況への自然な反応。","explanation":"変えられない状況への自然な反応。","explanationJa":"変えられない状況への自然な反応。","prompt":"Type the complete sentence you hear.","promptJa":"聞こえた英文をそのまま入力してください。","audioText":"It can’t be helped.","accepted":["It can’t be helped."]}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-speaking-1', 25, 'Listen & Speak', 'speaking', '{"id":"june-28-extra-speaking-1","format":"speaking","type":"speaking","section":"Listen & Speak","topic":"restaurants","isOriginal":false,"hint":"Could I have... は丁寧な依頼。","hintJa":"Could I have... は丁寧な依頼。","explanation":"Could I have... は丁寧な依頼。","explanationJa":"Could I have... は丁寧な依頼。","prompt":"Listen, then say the sentence naturally.","promptJa":"音声を聞いてから、自然に言ってみましょう。","speakText":"Could I have the menu?","speakJa":"メニューをいただけますか？"}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-speaking-2', 26, 'Listen & Speak', 'speaking', '{"id":"june-28-extra-speaking-2","format":"speaking","type":"speaking","section":"Listen & Speak","topic":"choices","isOriginal":false,"hint":"instead は「代わりに」。","hintJa":"instead は「代わりに」。","explanation":"instead は「代わりに」。","explanationJa":"instead は「代わりに」。","prompt":"Listen, then say the sentence naturally.","promptJa":"音声を聞いてから、自然に言ってみましょう。","speakText":"I ordered tea instead.","speakJa":"代わりに紅茶を注文しました。"}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-true-false', 27, 'Use It', 'truefalse', '{"id":"june-28-extra-true-false","format":"truefalse","type":"truefalse","section":"Use It","topic":"reactions","isOriginal":false,"hint":"提案への自然な反応。","hintJa":"提案への自然な反応。","explanation":"提案への自然な反応。","explanationJa":"提案への自然な反応。","prompt":"“That sounds good.” means “それはよさそうですね。”.","promptJa":"「That sounds good.」は「それはよさそうですね。」という意味です。","correct":true}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-order', 28, 'Use It', 'order', '{"id":"june-28-extra-order","format":"order","type":"order","section":"Use It","topic":"restaurants","isOriginal":false,"hint":"店員がよく使う丁寧な質問。","hintJa":"店員がよく使う丁寧な質問。","explanation":"店員がよく使う丁寧な質問。","explanationJa":"店員がよく使う丁寧な質問。","prompt":"Put the words in order: ほかに何かいかがですか？","promptJa":"語順を並べましょう：ほかに何かいかがですか？","words":["you","else","like","Would","anything"],"correctWords":["Would","you","like","anything","else"]}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-matching', 29, 'Use It', 'matching', '{"id":"june-28-extra-matching","format":"matching","type":"matching","section":"Use It","topic":"polite orders","isOriginal":false,"hint":"I’d like は丁寧な注文。","hintJa":"I’d like は丁寧な注文。","explanation":"I’d like は丁寧な注文。","explanationJa":"I’d like は丁寧な注文。","prompt":"Match each English phrase with its natural Japanese meaning.","promptJa":"英文と自然な日本語を組み合わせてください。","pairs":[{"en":"I’d like a coffee, please.","jp":"コーヒーをお願いします。","cat":"polite orders"},{"en":"How about you?","jp":"あなたはどうですか？","cat":"follow-up questions"},{"en":"What did you order?","jp":"何を注文しましたか？","cat":"past questions"},{"en":"It can’t be helped.","jp":"仕方ありません。","cat":"useful responses"},{"en":"Could I have the menu?","jp":"メニューをいただけますか？","cat":"restaurants"},{"en":"I ordered tea instead.","jp":"代わりに紅茶を注文しました。","cat":"choices"}]}'::jsonb, false, 6),
    ('june-28', 'june-28-extra-sorting', 30, 'Use It', 'sorting', '{"id":"june-28-extra-sorting","format":"sorting","type":"sorting","section":"Use It","topic":"follow-up questions","isOriginal":false,"hint":"相手にも同じ質問を返す。","hintJa":"相手にも同じ質問を返す。","explanation":"相手にも同じ質問を返す。","explanationJa":"相手にも同じ質問を返す。","prompt":"Sort each phrase by its language purpose.","promptJa":"各表現を目的別に分類してください。","categories":["polite orders","follow-up questions"],"items":[["I’d like a coffee, please.","polite orders"],["How about you?","follow-up questions"]]}'::jsonb, false, 2),
    ('june-28', 'june-28-extra-dialogue', 31, 'Use It', 'dialogue', '{"id":"june-28-extra-dialogue","format":"dialogue","type":"dialogue","section":"Use It","topic":"follow-up questions","isOriginal":false,"hint":"相手にも同じ質問を返す。","hintJa":"相手にも同じ質問を返す。","explanation":"相手にも同じ質問を返す。","explanationJa":"相手にも同じ質問を返す。","prompt":"Choose the most natural next line in the conversation.","promptJa":"会話の次に続く最も自然な一文を選んでください。","context":"A: I’d like a coffee, please. What can A ask the other person next?","contextJa":"A：「コーヒーをお願いします。」続けて相手の希望を聞くなら？","choices":[{"id":"a","en":"How about you?","jp":"あなたはどうですか？"},{"id":"b","en":"What did you order?","jp":"何を注文しましたか？"},{"id":"c","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"d","en":"Could I have the menu?","jp":"メニューをいただけますか？"}],"correct":"a"}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-translation', 32, 'Use It', 'translation', '{"id":"june-28-extra-translation","format":"translation","type":"translation","section":"Use It","topic":"past questions","isOriginal":false,"hint":"did の後は動詞の原形。","hintJa":"did の後は動詞の原形。","explanation":"did の後は動詞の原形。","explanationJa":"did の後は動詞の原形。","prompt":"Translate into English: 何を注文しましたか？","promptJa":"英語にしてください：何を注文しましたか？","accepted":["What did you order?"]}'::jsonb, false, 1),
    ('june-28', 'june-28-extra-situation', 33, 'Use It', 'situation', '{"id":"june-28-extra-situation","format":"situation","type":"situation","section":"Use It","topic":"useful responses","isOriginal":false,"hint":"変えられない状況への自然な反応。","hintJa":"変えられない状況への自然な反応。","explanation":"変えられない状況への自然な反応。","explanationJa":"変えられない状況への自然な反応。","prompt":"Which sentence best expresses this meaning: 仕方ありません。","promptJa":"「仕方ありません。」に最も合う英文はどれですか？","choices":[{"id":"a","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"b","en":"Could I have the menu?","jp":"メニューをいただけますか？"},{"id":"c","en":"I ordered tea instead.","jp":"代わりに紅茶を注文しました。"},{"id":"d","en":"That sounds good.","jp":"それはよさそうですね。"}],"correct":"a"}'::jsonb, false, 1),
    ('june-29', 'june-29-original-q1', 0, 'Original Review', 'mcq', '{"id":"june-29-original-q1","type":"mcq","cat":"heard","prompt":{"en":"Which sentence means 「それ聞こえた」?","jp":"「それ聞こえた」はどれですか？"},"choices":[{"id":"a","en":"I heard it.","jp":"それ聞こえた。"},{"id":"b","en":"I heard that.","jp":"それ聞いたよ。"},{"id":"c","en":"I heard about it.","jp":"それについて聞いた。"},{"id":"d","en":"I''ve heard of it.","jp":"名前は聞いたことある。"}],"correct":"a","hint":{"en":"Think about sound or voice reaching your ears.","jp":"音や声が耳に入ったイメージです。"},"explanation":{"en":"“I heard it” is used when you heard a sound, voice, or something someone said.","jp":"“I heard it.” は、音・声・何かが耳に入ったときに使います。「それ聞こえた」という感じです。"},"legacyId":"q1","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q2', 1, 'Original Review', 'mcq', '{"id":"june-29-original-q2","type":"mcq","cat":"heard","prompt":{"en":"Which sentence means 「それ聞いたよ」 as information?","jp":"情報として「それ聞いたよ」はどれですか？"},"choices":[{"id":"a","en":"I heard it.","jp":"それ聞こえた。"},{"id":"b","en":"I heard that.","jp":"それ聞いたよ。"},{"id":"c","en":"I heard about it.","jp":"それについて聞いた。"},{"id":"d","en":"I''ve heard of it.","jp":"名前は聞いたことある。"}],"correct":"b","hint":{"en":"This is about information or content, not just sound.","jp":"音ではなく、内容・情報を聞いた感じです。"},"explanation":{"en":"“I heard that” is used when you heard some information or content.","jp":"“I heard that.” は、内容や情報を聞いたときに使います。「その話聞いたよ」という感じです。"},"legacyId":"q2","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q3', 2, 'Original Review', 'mcq', '{"id":"june-29-original-q3","type":"mcq","cat":"heard","prompt":{"en":"Which sentence means 「それについて聞いた」?","jp":"「それについて聞いた」はどれですか？"},"choices":[{"id":"a","en":"I heard it.","jp":"それ聞こえた。"},{"id":"b","en":"I heard that.","jp":"それ聞いたよ。"},{"id":"c","en":"I heard about it.","jp":"それについて聞いた。"},{"id":"d","en":"I''ve heard of it.","jp":"名前は聞いたことある。"}],"correct":"c","hint":{"en":"Use this when talking about a topic, event, story, or news.","jp":"話題・出来事・ニュースについて聞いたときに使います。"},"explanation":{"en":"“I heard about it” means you heard some information about a topic, event, or situation.","jp":"“I heard about it.” は、ある話題や出来事について聞いたときに使います。「そのことについて聞いた」という感じです。"},"legacyId":"q3","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q4', 3, 'Original Review', 'mcq', '{"id":"june-29-original-q4","type":"mcq","cat":"heard","prompt":{"en":"Which sentence means 「名前は聞いたことある」?","jp":"「名前は聞いたことある」はどれですか？"},"choices":[{"id":"a","en":"I heard it.","jp":"それ聞こえた。"},{"id":"b","en":"I heard that.","jp":"それ聞いたよ。"},{"id":"c","en":"I heard about it.","jp":"それについて聞いた。"},{"id":"d","en":"I''ve heard of it.","jp":"名前は聞いたことある。"}],"correct":"d","hint":{"en":"You know the name, but maybe you do not know the details.","jp":"名前や存在は知っているけど、詳しくは知らない感じです。"},"explanation":{"en":"“I''ve heard of it” means you know the name or existence of something, but you may not know the details.","jp":"“I''ve heard of it.” は、名前や存在を聞いたことがあるときに使います。詳しい内容までは知らなくても大丈夫です。"},"legacyId":"q4","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q5', 4, 'Original Review', 'situation', '{"id":"june-29-original-q5","type":"situation","cat":"heard","situationQuote":{"en":"“There is a new restaurant near the station. Have you heard about it?”"},"prompt":{"en":"What is the best answer?","jp":"友達が「駅の近くに新しいレストランがあるんだけど、そのこと聞いた？」と言っています。自然な返事はどれですか？"},"choices":[{"id":"a","en":"I think I heard about it.","jp":"それについて聞いた気がする。"},{"id":"b","en":"I think I heard it.","jp":"それが聞こえた気がする。"},{"id":"c","en":"I think I heard of that.","jp":"名前は聞いたことある気がする。"},{"id":"d","en":"I am hearing it.","jp":"不自然な英語です。"}],"correct":"a","hint":{"en":"The friend is asking about a topic or news.","jp":"話題・ニュースについて聞かれています。"},"explanation":{"en":"“I think I heard about it” is natural because the topic is a new restaurant or news.","jp":"新しいレストランという話題について聞いているので、“I think I heard about it.” が自然です。"},"legacyId":"q5","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q6', 5, 'Original Review', 'mcq', '{"id":"june-29-original-q6","type":"mcq","cat":"reactions","prompt":{"en":"Which phrase means 「それなぁ！」?","jp":"「それなぁ！」に近い英語はどれですか？"},"choices":[{"id":"a","en":"Exactly.","jp":"それなぁ。"},{"id":"b","en":"It''s okay.","jp":"大丈夫だよ。"},{"id":"c","en":"That''s tough.","jp":"それは大変だね。"},{"id":"d","en":"That sounds good.","jp":"それいいね。"}],"correct":"a","hint":{"en":"Use this when you strongly agree.","jp":"強く同意するときに使います。"},"explanation":{"en":"“Exactly” is used when you strongly agree with what someone said.","jp":"“Exactly.” は、相手の言ったことに強く同意するときに使います。「それなぁ」「まさにそう」という感じです。"},"legacyId":"q6","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q7', 6, 'Original Review', 'situation', '{"id":"june-29-original-q7","type":"situation","cat":"reactions","situationQuote":{"en":"“Learning English every day is important.”"},"prompt":{"en":"Choose the best natural reaction.","jp":"友達が「毎日英語を勉強するのは大事だよね」と言いました。自然な反応はどれですか？"},"choices":[{"id":"a","en":"That''s so true.","jp":"それほんとだよね。"},{"id":"b","en":"It can''t be helped.","jp":"仕方ない。"},{"id":"c","en":"I heard it.","jp":"それ聞こえた。"},{"id":"d","en":"Top right.","jp":"右上。"}],"correct":"a","hint":{"en":"Choose a phrase for agreeing with an opinion.","jp":"意見に共感・同意するときの表現です。"},"explanation":{"en":"“That''s so true” is a natural reaction when you agree with someone''s opinion.","jp":"“That''s so true.” は、相手の意見に共感するときに使えます。「それほんとだよね」という感じです。"},"legacyId":"q7","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q8', 7, 'Original Review', 'mcq', '{"id":"june-29-original-q8","type":"mcq","cat":"reactions","prompt":{"en":"Which phrase means 「マジで / ほんとそれ」 casually?","jp":"カジュアルに「マジで / ほんとそれ」はどれですか？"},"choices":[{"id":"a","en":"For real.","jp":"マジで / ほんとそれ。"},{"id":"b","en":"It''s okay.","jp":"大丈夫だよ。"},{"id":"c","en":"That sounds good.","jp":"それいいね。"},{"id":"d","en":"I heard that.","jp":"それ聞いたよ。"}],"correct":"a","hint":{"en":"This is casual and conversational.","jp":"カジュアルな会話で使います。"},"explanation":{"en":"“For real” is a casual phrase used to show agreement, surprise, or strong feeling.","jp":"“For real.” はカジュアルな表現で、「マジで」「ほんとそれ」のように使えます。"},"legacyId":"q8","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q9', 8, 'Original Review', 'mcq', '{"id":"june-29-original-q9","type":"mcq","cat":"position","prompt":{"en":"What does “top right” mean?","jp":"“top right” はどこの位置ですか？"},"choices":[{"id":"a","en":"右上","jp":"top right"},{"id":"b","en":"左上","jp":"top left"},{"id":"c","en":"右下","jp":"bottom right"},{"id":"d","en":"左下","jp":"bottom left"}],"correct":"a","hint":{"en":"Top means 上. Right means 右.","jp":"top = 上、right = 右です。"},"explanation":{"en":"“Top right” means the upper-right position.","jp":"“top right” は「右上」という意味です。top が上、right が右です。"},"legacyId":"q9","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q10', 9, 'Original Review', 'grid', '{"id":"june-29-original-q10","type":"grid","cat":"position","prompt":{"en":"Click the bottom left box.","jp":"左下のマスをクリックしてください。"},"correctCell":"bottom-left","hint":{"en":"Bottom means 下. Left means 左.","jp":"bottom = 下、left = 左です。"},"explanation":{"en":"“Bottom left” is the box in the lower-left corner — bottom (下) + left (左).","jp":"“bottom left” は左下のマスです。bottom = 下、left = 左です。"},"legacyId":"q10","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q11', 10, 'Original Review', 'matching', '{"id":"june-29-original-q11","type":"matching","cat":"mixed","prompt":{"en":"Match the English phrase with the Japanese meaning.","jp":"英語のフレーズと日本語の意味をマッチさせましょう。"},"hint":{"en":"Think back to the phrases you just reviewed above.","jp":"これまで復習した表現を思い出してみましょう。"},"pairs":[{"en":"I heard it.","jp":"それ聞こえた。","cat":"heard"},{"en":"I heard that.","jp":"それ聞いたよ。","cat":"heard"},{"en":"I heard about it.","jp":"それについて聞いた。","cat":"heard"},{"en":"I''ve heard of it.","jp":"名前は聞いたことある。","cat":"heard"},{"en":"Exactly.","jp":"それなぁ。","cat":"reactions"},{"en":"For real.","jp":"マジで / ほんとそれ。","cat":"reactions"},{"en":"top right.","jp":"右上。","cat":"position"},{"en":"bottom left.","jp":"左下。","cat":"position"}],"legacyId":"q11","section":"Original Review","isOriginal":true}'::jsonb, true, 8),
    ('june-29', 'june-29-original-q12a', 11, 'Original Review', 'typing', '{"id":"june-29-original-q12a","type":"typing","cat":"heard","promptJP":"「それについて聞いた気がする。」","accepted":["I think I heard about it"],"hint":{"en":"This is about a topic or piece of news, not just a sound.","jp":"話題やニュースについてです。音だけではありません。"},"explanation":{"en":"“I think I heard about it” fits because it''s about a topic or story, not a sound.","jp":"話題や出来事について聞いた場合は “I heard about it” を使います。"},"legacyId":"q12a","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q12b', 12, 'Original Review', 'typing', '{"id":"june-29-original-q12b","type":"typing","cat":"heard","promptJP":"「名前は聞いたことある。」","accepted":["I''ve heard of it","I have heard of it"],"hint":{"en":"You recognize the name, but maybe not the details.","jp":"名前は知っているけど、詳しくは知らないイメージです。"},"explanation":{"en":"“I''ve heard of it” is for names or things you recognize but don''t know in detail.","jp":"名前や存在を知っているときは “I''ve heard of it” が自然です。"},"legacyId":"q12b","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q12c', 13, 'Original Review', 'typing', '{"id":"june-29-original-q12c","type":"typing","cat":"reactions","promptJP":"「それほんとだよね。」","accepted":["That''s so true"],"hint":{"en":"This shows warm agreement with someone''s opinion.","jp":"相手の意見に温かく同意する表現です。"},"explanation":{"en":"“That''s so true” is a warm, natural way to agree with someone''s feeling or opinion.","jp":"相手の意見に共感するときは “That''s so true” が自然です。"},"legacyId":"q12c","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-original-q12d', 14, 'Original Review', 'typing', '{"id":"june-29-original-q12d","type":"typing","cat":"position","promptJP":"「右上」","accepted":["top right"],"hint":{"en":"Top means 上, right means 右.","jp":"top = 上、right = 右です。"},"explanation":{"en":"“Top right” describes the upper-right position — top is 上, right is 右.","jp":"“top right” は「右上」、top = 上、right = 右です。"},"legacyId":"q12d","section":"Original Review","isOriginal":true}'::jsonb, true, 1),
    ('june-29', 'june-29-extra-listen-choice-1', 15, 'Listen & Speak', 'listenChoice', '{"id":"june-29-extra-listen-choice-1","format":"listenChoice","type":"listenChoice","section":"Listen & Speak","topic":"hear","isOriginal":false,"hint":"出来事・話題には hear about。","hintJa":"出来事・話題には hear about。","explanation":"出来事・話題には hear about。","explanationJa":"出来事・話題には hear about。","prompt":"Listen and choose the sentence you hear.","promptJa":"音声を聞いて、聞こえた英文を選んでください。","audioText":"I heard about it yesterday.","choices":[{"id":"a","en":"I heard about it yesterday.","jp":"昨日そのことについて聞きました。"},{"id":"b","en":"I’ve heard of that restaurant.","jp":"そのレストランの名前は聞いたことがあります。"},{"id":"c","en":"I heard it clearly.","jp":"それがはっきり聞こえました。"},{"id":"d","en":"Exactly. That’s what I mean.","jp":"その通り。それが私の言いたいことです。"}],"correct":"a"}'::jsonb, false, 1),
