    ('june-29', 'june-29-extra-dictation-1', 17, 'Listen & Speak', 'listenType', '{"id":"june-29-extra-dictation-1","format":"listenType","type":"listenType","section":"Listen & Speak","topic":"hear","isOriginal":false,"hint":"音そのものを目的語にする。","hintJa":"音そのものを目的語にする。","explanation":"音そのものを目的語にする。","explanationJa":"音そのものを目的語にする。","prompt":"Type the complete sentence you hear.","promptJa":"聞こえた英文をそのまま入力してください。","audioText":"I heard it clearly.","accepted":["I heard it clearly."]}'::jsonb, false, 1),
